(window.WCD=window.WCD||[]).push(["sports",[["Q180872",1,"tennis","Amélie Mauresmo","PC","Amélie Mauresmo, née le 5 juillet 1979 à Saint-Germain-en-Laye, est une joueuse de tennis française, devenue entraîneuse et dirigeante. Elle est l'actuelle directrice du tournoi de Roland-Garros.",108,"fr:Amélie_Mauresmo","c:3/3b/Amelie_Mauresmo_Australian_Open_2005_%28cropped%29.jpg",{"cats":["sports","tennis"]}],["Q30758",2,"tennis","Ana Ivanović","PC","Ana Ivanović est une joueuse de tennis serbe, née le 6 novembre 1987 à Belgrade.",null,"fr:Ana_Ivanović","c:b/b9/Ana_Ivanovic_%2818407719442%29.jpg",{"cats":["sports","tennis"]}],["Q7407",3,"tennis","Andre Agassi","L","Andre Agassi, né le 29 avril 1970 à Las Vegas, est un joueur de tennis américain, professionnel de 1986 à 2006.",null,"fr:Andre_Agassi","c:7/7a/Andre_Agassi.jpg",{"cats":["sports","tennis"]}],["Q10125",4,"tennis","Andy Murray","E","Sir Andrew Murray, dit Andy Murray, né le 15 mai 1987 à Glasgow, est un joueur de tennis britannique, professionnel de 2005 à 2024.",118,"fr:Andy_Murray","c:3/36/Andy_Murray_Tokyo_2011.jpg",{"cats":["sports","tennis"]}],["Q54584",5,"tennis","Andy Roddick","R","Andrew Stephen Roddick, dit Andy Roddick, né le 30 août 1982 à Omaha dans le Nebraska, est un joueur de tennis américain.",110,"fr:Andy_Roddick","c:5/5f/Roddick_2012.jpg",{"cats":["sports","tennis"]}],["Q77178",6,"tennis","Angelique Kerber","R","Angelique Kerber, née le 18 janvier 1988 à Brême, est une joueuse de tennis professionnelle allemande.",null,"fr:Angelique_Kerber","c:3/36/2021-06_Angelique_Kerber_%28cropped%29_%28cropped%29.jpg",{"cats":["sports","tennis"]}],["Q131120",7,"tennis","Anna Kournikova","E","Anna Kournikova, née le 7 juin 1981 à Moscou, est une joueuse de tennis russe, professionnelle de 1995 à 2003.",null,"fr:Anna_Kournikova","c:4/48/Anna_Kournikova-Bagram_Airfield_2009.jpg",{"cats":["sports","tennis"]}],["Q53325",8,"tennis","Arthur Ashe","R","Arthur Ashe, né le 10 juillet 1943 à Richmond et mort le 6 février 1993 à New York, est un joueur de tennis américain, professionnel de 1968 à 1980.",118,"fr:Arthur_Ashe","c:6/60/Arthur_Ashe_%28cropped%29.jpg",{"cats":["sports","tennis"]}],["Q107207693",9,"tennis","Arthur Fils","R","Arthur Fils, né le 12 juin 2004 à Courcouronnes, est un joueur de tennis français, professionnel depuis 2021.",null,"fr:Arthur_Fils","c:a/ae/Arthur_Fils_-_2024_Olympics_%28still%29_%28cropped%29.jpg",{"cats":["sports","tennis"]}],["Q23448791",10,"tennis","Aryna Sabalenka","E","Aryna Sabalenka est une joueuse de tennis biélorusse, née le 5 mai 1998 à Minsk.",null,"fr:Aryna_Sabalenka","c:5/57/Aryna_Sabalenka_Miami_Open_Final.jpg",{"cats":["sports","tennis"]}],["Q54527",11,"tennis","Billie Jean King","E","Billie Jean King, née Billie Jean Moffitt le 22 novembre 1943 à Long Beach, est une joueuse de tennis américaine, dont la carrière s'étend de 1959 à 1983 en simple et jusqu'en 1990 en double.",118,"fr:Billie_Jean_King","c:3/35/BJK_headshot_2011_5x7_300dpi.jpg",{"cats":["sports","tennis","lgbt"]}],["Q104506",12,"tennis","Björn Borg","R","Björn Borg, né le 6 juin 1956 à Stockholm et ayant passé sa jeunesse à Södertälje, est un joueur de tennis professionnel suédois, dont la carrière s'étend de 1973 à 1984. Il fait un retour en 1991 pour prendre sa retraite définitive en 1993.",106,"fr:Björn_Borg","c:4/4a/Bj%C3%B6rn_Borg_2013-11-06_001_%28cropped%29.jpg",{"cats":["sports","tennis"]}],["Q76334",13,"tennis","Boris Becker","E","Boris Franz Becker, né à Leimen le 22 novembre 1967, est un joueur de tennis allemand, professionnel entre 1984 et 1999.",null,"fr:Boris_Becker","c:2/23/BECKER_Boris-24x30-.jpg",{"cats":["sports","tennis"]}],["Q85518537",14,"tennis","Carlos Alcaraz","M","Carlos Alcaraz, né le 5 mai 2003 à El Palmar, est un joueur de tennis espagnol, professionnel depuis 2018. Il est parmi les tout meilleurs joueurs en simple au classement ATP. À 22 ans et 272 jours, il devient le plus jeune joueur de l'histoire à avoir remporté les quatre tournois du Grand Chelem.","Carlos Alcaraz, né le 5 mai 2003 à El Palmar, est un joueur de tennis espagnol, professionnel depuis 2018.","fr:Carlos_Alcaraz","c:d/d4/25th_Laureus_World_Sports_Awards_-_Red_Carpet_-_Carlos_Alcaraz_-_240422_192324_%28cropped%29.jpg",{"cats":["sports","tennis"]}],["Q30767",15,"tennis","Caroline Wozniacki","PC","Caroline Wozniacki, née le 11 juillet 1990 à Odense, est une joueuse de tennis danoise, première mondiale pendant 71 semaines. Elle est la seule joueuse danoise de l'histoire à avoir atteint un tel niveau.",116,"fr:Caroline_Wozniacki","c:a/ad/Caroline_Wozniacki_%28Den%29_%2824852316737%29_%282%29_%28cropped%29.jpg",{"cats":["sports","tennis"]}],["Q14286",16,"tennis","Chris Evert","R","Christine Marie Evert, plus connue sous le nom de Chris Evert, est une joueuse de tennis américaine née le 21 décembre 1954 à Fort Lauderdale, en Floride.",118,"fr:Chris_Evert","c:2/21/Chris_Evert.jpg",{"cats":["sports","tennis"]}],["Q39263365",17,"tennis","Coco Gauff","E","Cori Dionne Gauff, généralement surnommée Coco Gauff, née le 13 mars 2004 à Delray Beach, est une joueuse de tennis américaine, professionnelle depuis 2018. À ce jour, elle compte douze titres en simple et dix titres en double dames sur le circuit WTA.",115,"fr:Coco_Gauff","c:a/ac/US_Open_2022_Photo_177_%2852391301928%29_%28Gauff%29.jpg",{"cats":["sports","tennis"]}],["Q17381675",19,"tennis","Elise Mertens","R","Elise Mertens, née le 17 novembre 1995 à Louvain, est une joueuse de tennis belge, professionnelle depuis 2013.",null,"fr:Elise_Mertens","c:6/62/Elise_Mertens_%2849985630033%29_%28cropped%29.jpg",{"cats":["sports","tennis"]}],["Q34276",20,"tennis","Garbiñe Muguruza","PC","Garbiñe Muguruza Blanco, née le 8 octobre 1993 à Caracas, est une joueuse de tennis hispano-vénézuélienne jouant pour l'Espagne.",117,"fr:Garbiñe_Muguruza","c:e/ec/Muguruza_WM19_%2866%29_%2848521961407%29.jpg",{"cats":["sports","tennis"]}],["Q186429",21,"tennis","Gaël Monfils","L","Gaël Monfils, né le 1er septembre 1986 à Paris, est un joueur de tennis français, professionnel de 2004 à 2026.",null,"fr:Gaël_Monfils","c:a/a0/Ga%C3%ABl_Monfils_at_Sports_Festival_2026.jpg",{"cats":["sports","tennis"]}],["Q26840238",22,"tennis","Iga Świątek","E","Iga Świątek, née le 31 mai 2001 à Varsovie, est une joueuse de tennis polonaise.",null,"fr:Iga_Świątek","c:3/3c/Iga_%C5%9Awi%C4%85tek_%282023_US_Open%29_18_%28cropped%29.jpg",{"cats":["sports","tennis"]}],["Q182736",23,"tennis","Ivan Lendl","R","Ivan Lendl, né le 7 mars 1960 à Ostrava, est un joueur de tennis tchécoslovaque naturalisé américain depuis 1992.",null,"fr:Ivan_Lendl","c:3/3b/Ivan_Lendl.jpg",{"cats":["sports","tennis"]}],["Q54812588",24,"tennis","Jannik Sinner","L","Jannik Sinner, né le 16 août 2001 à San Candido, est un joueur de tennis italien, professionnel depuis 2018. Il est parmi les tout meilleurs joueurs en simple au classement ATP. Il est par ailleurs le premier Italien à avoir atteint la place de numéro 1 mondial.","Jannik Sinner, né le 16 août 2001 à San Candido, est un joueur de tennis italien, professionnel depuis 2018.","fr:Jannik_Sinner","c:6/64/Jannik_Sinner_2025_US_Open.jpg",{"cats":["sports","tennis"]}],["Q53393",25,"tennis","Jimmy Connors","R","James Connors, dit Jimmy Connors, né le 2 septembre 1952 à East Saint Louis dans l'Illinois, est un joueur de tennis américain professionnel.",116,"fr:Jimmy_Connors","c:9/97/Jimmy_Conners_1994.jpg",{"cats":["sports","tennis"]}],["Q192661",26,"tennis","Jo-Wilfried Tsonga","PC","Jo-Wilfried Tsonga, né le 17 avril 1985 au Mans, est un joueur de tennis français, professionnel entre 2004 et 2022.",null,"fr:Jo-Wilfried_Tsonga","c:d/df/Jo-Wilfried_Tsonga_%2835355612006%29.jpg",{"cats":["sports","tennis"]}],["Q16474",27,"tennis","John McEnroe","E","John McEnroe, né le 16 février 1959 à Wiesbaden, est un joueur de tennis américain, professionnel de 1977 à 1992.",null,"fr:John_McEnroe","c:b/bf/John_McEnroe_005.png",{"cats":["sports","tennis"]}],["Q180446",30,"tennis","Li Na","R","Li Na, née le 26 février 1982 à Wuhan, est une ancienne joueuse de tennis chinoise, professionnelle entre 1999 et 2014.",null,"fr:Li_Na_(tennis)","c:5/58/Li_Na_Wimbledon_2013.jpg",{"cats":["sports","tennis"]}],["Q133318",31,"tennis","Marat Safin","R","Marat Moubinovitch Safin, né le 27 janvier 1980 à Moscou, est un joueur de tennis et homme politique russe.",null,"fr:Marat_Safin","c:c/c9/Marat_Safin_US_Open_08.jpg",{"cats":["sports","tennis"]}],["Q11666",32,"tennis","Maria Sharapova","E","Maria Yourievna Sharapova, née le 19 avril 1987 à Niagan en Sibérie, est une joueuse professionnelle de tennis russe dont la carrière internationale s'étend de 2001 à 2020.",116,"fr:Maria_Sharapova","c:b/bc/Maria_Sharapova_during_opening_night_of_Web_Summit_2025_at_the_MEO_Arena_in_Lisbon%2C_Portugal.jpg",{"cats":["sports","tennis"]}],["Q134720",33,"tennis","Martina Hingis","R","Martina Hingis, née le 30 septembre 1980 à Košice, est une joueuse de tennis professionnelle suisse. Elle détient le record de la plus jeune gagnante d'un titre du Grand Chelem en simple dans l'ère Open, et celui de la plus jeune numéro un mondiale de l'histoire du tennis.","Martina Hingis, née le 30 septembre 1980 à Košice, est une joueuse de tennis professionnelle suisse.","fr:Martina_Hingis","c:9/96/Martina_Hingis_%2819482582291%29.jpg",{"cats":["sports","tennis"]}],["Q54545",34,"tennis","Martina Navrátilová","E","Martina Navrátilová, née le 18 octobre 1956 à Prague en Tchécoslovaquie, est une joueuse de tennis tchécoslovaque, devenue citoyenne américaine en 1981.",114,"fr:Martina_Navrátilová","c:5/52/25th_Laureus_World_Sports_Awards_-_Red_Carpet_-_Martina_Navratilova_-_240422_183713_%28cropped%29.jpg",{"cats":["sports","tennis"]}],["Q173633",35,"tennis","Monica Seles","E","Monica Seles est une joueuse de tennis yougoslave, puis américaine, née le 2 décembre 1973 à Novi Sad.",null,"fr:Monica_Seles","c:0/08/Monica_Seles_1999.jpg",{"cats":["sports","tennis"]}],["Q17466583",36,"tennis","Naomi Osaka","E","Naomi Osaka, née le 16 octobre 1997 à Osaka, est une joueuse de tennis japonaise, professionnelle depuis 2012. Sa mère est japonaise et son père est haïtien. Elle vit aux États-Unis depuis l’âge de trois ans et possède, en plus de la nationalité japonaise, la nationalité américaine qu’elle abandonne en octobre 2019 comme l’y oblige la loi japonaise qui refuse la double nationalité au-delà de l’âge de 22 ans.","Naomi Osaka, née le 16 octobre 1997 à Osaka, est une joueuse de tennis japonaise, professionnelle depuis 2012.","fr:Naomi_Osaka","c:5/53/NaomiOsaka-smile-2020.png",{"cats":["sports","tennis","sante_mentale"]}],["Q5812",37,"tennis","Novak Djokovic","M","Novak Djokovic, né le 22 mai 1987 à Belgrade, est un joueur de tennis serbe, professionnel depuis 2003.",null,"fr:Novak_Djokovic","c:d/d1/Novak_Djokovic_Paris_2024_Olympic_Games_%28cropped%29.jpg",{"cats":["sports","tennis"]}],["Q9446",38,"tennis","Pete Sampras","E","Petros Sampras, dit Pete Sampras, né le 12 août 1971 à Washington, est un joueur de tennis américain.",null,"fr:Pete_Sampras","c:9/9c/Pete_Sampras_Champions_Shootout_2.jpg",{"cats":["sports","tennis"]}],["Q30812",39,"tennis","Petra Kvitová","PC","Petra Kvitová, est une joueuse de tennis tchèque, née le 8 mars 1990 à Bílovec.",null,"fr:Petra_Kvitová","c:5/57/Petra_Kvitov%C3%A1_Birmingham_2018.jpg",{"cats":["sports","tennis"]}],["Q10132",40,"tennis","Rafael Nadal","L","Rafael Nadal Parera, plus simplement appelé Rafa Nadal, né le 3 juin 1986 à Manacor, est un joueur de tennis espagnol, professionnel de 2001 à 2024.",118,"fr:Rafael_Nadal","c:3/30/Rafael_Nadal_2011_Roland_Garros_2011.jpg",{"cats":["sports","tennis"]}],["Q209436",41,"tennis","Richard Gasquet","PC","Richard Gasquet, né le 18 juin 1986 à Béziers, est un joueur français de tennis professionnel de 2002 à 2025.",null,"fr:Richard_Gasquet","c:0/01/Paris-FR-75-open_de_tennis-25-5-16-Roland_Garros-Richard_Gasquet-33.jpg",{"cats":["sports","tennis"]}],["Q105550",42,"tennis","Rod Laver","PC","Rodney George Laver, dit Rod Laver, né le 9 août 1938 à Rockhampton, est un joueur de tennis professionnel australien.",null,"fr:Rod_Laver","c:e/e9/Rodney_George_Laver.jpg",{"cats":["sports","tennis"]}],["Q1426",43,"tennis","Roger Federer","L","Roger Federer, né le 8 août 1981 à Bâle, est un joueur de tennis suisse, professionnel de 1998 à 2022. Il est considéré, avec Rafael Nadal et Novak Djokovic, comme l'un des meilleurs joueurs de tennis de tous les temps, formant à eux trois le Big Three.","Roger Federer, né le 8 août 1981 à Bâle, est un joueur de tennis suisse, professionnel de 1998 à 2022.","fr:Roger_Federer","c:4/40/Roger_Federer_%2826_June_2009%2C_Wimbledon%29_2.jpg",{"cats":["sports","tennis"]}],["Q132147",44,"tennis","Sania Mirza","R","Sania Mirza est une joueuse de tennis indienne, professionnelle de 2003 à 2023, née le 15 novembre 1986 à Bombay.",null,"fr:Sania_Mirza","c:8/8e/Sania_Mirza_%2835449409862%29.jpg",{"cats":["sports","tennis"]}],["Q11459",45,"tennis","Serena Williams","E","Serena Jameka Williams est une joueuse de tennis américaine née le 26 septembre 1981 à Saginaw. Considérée comme l'une des plus grandes joueuses de tous les temps, elle a remporté 39 titres du Grand Chelem en simple et en double, soit 7 Open d'Australie, 3 Roland-Garros, 7 Wimbledon et 6 US Open en simple; 4 Open d'Australie, 2 Roland-Garros, 6 Wimbledon et 2 US Open en double dames avec sa sœur Venus Williams et 1 Wimbledon et 1 US Open en double mixte.","Serena Jameka Williams est une joueuse de tennis américaine née le 26 septembre 1981 à Saginaw.","fr:Serena_Williams","c:d/d3/Serena_Williams_at_the_2025_International_Tennis_Hall_of_Fame_Induction_Ceremony_Press_Conference_%28cropped%29.jpg",{"cats":["sports","tennis"]}],["Q230156",46,"tennis","Simona Halep","PC","Simona Halep, née le 27 septembre 1991 à Constanța, est une joueuse de tennis roumaine. Professionnelle de 2008 à 2025, elle a remporté vingt-quatre tournois en simple sur le circuit WTA.","Simona Halep, née le 27 septembre 1991 à Constanța, est une joueuse de tennis roumaine.","fr:Simona_Halep","c:a/a8/Sydney_International_Tennis_WTA_%2833040181638%29_%28cropped%29.jpg",{"cats":["sports","tennis"]}],["Q193661",47,"tennis","Stanislas Wawrinka","E","Stanislas Wawrinka, également connu sous la forme abrégée Stan Wawrinka, né le 28 mars 1985 à Lausanne, est un joueur de tennis suisse, professionnel de 2002 à 2026.",117,"fr:Stanislas_Wawrinka","c:f/fe/Stan_Wawrinka_%2849985471396%29_%28cropped%29.jpg",{"cats":["sports","tennis"]}],["Q11662",48,"tennis","Steffi Graf","M","Stefanie Graf, dite Steffi Graf, est une joueuse de tennis allemande, née le 14 juin 1969 à Mannheim en République fédérale d'Allemagne.",114,"fr:Steffi_Graf","c:5/5b/Steffi_Graf_in_Hamburg.jpg",{"cats":["sports","tennis"]}],["Q232831",49,"tennis","Suzanne Lenglen","C","Suzanne Rachel Flore Lenglen, née le 24 mai 1899 à Paris où elle est morte le 4 juillet 1938, est une joueuse de tennis française. Surnommée « la Divine », elle fut la première star internationale du tennis féminin.",119,"fr:Suzanne_Lenglen","c:5/5f/Suzanne_Lenglen_02.jpg",{"cats":["sports","tennis"]}],["Q54007306",50,"tennis","Ugo Humbert","PC","Ugo Humbert, né le 26 juin 1998 à Metz, est un joueur de tennis français, professionnel depuis 2016.",null,"fr:Ugo_Humbert","c:3/3b/Ugo_Humbert_-_2024_Olympics_%28portrait%29_%28cropped%29.jpg",{"cats":["sports","tennis"]}],["Q11578",51,"tennis","Venus Williams","R","Venus Williams, née le 17 juin 1980 à Lynwood, est une joueuse de tennis américaine, professionnelle sur le circuit WTA depuis 1994.",119,"fr:Venus_Williams","c:1/19/Venus_Williams_%282025_DC_Open%29_crop.jpg",{"cats":["sports","tennis"]}],["Q10118",52,"tennis","Victoria Azarenka","PC","Victoria Azarenka, née le 31 juillet 1989 à Minsk, est une joueuse de tennis biélorusse, professionnelle depuis 2003.",null,"fr:Victoria_Azarenka","c:5/5a/Azarenka_WM18_%2854%29_%2830063338118%29.jpg",{"cats":["sports","tennis"]}],["Q15987809",90,"mma","Alex Pereira","E","Alex Pereira, né le 7 juillet 1987 à São Bernardo do Campo, est un pratiquant brésilien d'arts martiaux mixtes et ancien kick-boxeur. Il combat actuellement dans la catégorie des poids lourds de l'Ultimate Fighting Championship.",113,"fr:Alex_Pereira","c:c/c7/Alex_Pereira_in_the_Oval_Office_%28while_President_Donald_J._Trump_is_holding_a_meeting_with_UFC_fighters%29.jpg",{"cats":["sports","combat"]}],["Q356871",91,"mma","Anderson Silva","PC","Anderson da Silva, né le 14 avril 1975 à São Paulo, est un pratiquant brésilien d'arts martiaux mixtes.",null,"fr:Anderson_Silva","c:a/a2/Anderson_Silva.png",{"cats":["sports","combat"]}],["Q112241194",92,"mma","Benoît Saint Denis","R","Benoît Saint Denis, dont le nom est fréquemment abrégé à ses initiales, né le 18 décembre 1995 à Nîmes, est un pratiquant français d'arts martiaux mixtes et un ancien militaire des forces spéciales françaises.",110,"fr:Benoît_Saint_Denis","c:2/2c/Beno%C3%AEt_SAINT_DENIS_combattant_UFC.jpg",{"cats":["sports","combat"]}],["Q79372882",93,"mma","Ciryl Gane","R","Ciryl Gane, surnommé « Bon Gamin », né le 12 avril 1990 à La Roche-sur-Yon, est un pratiquant français de muay-thaï et d'arts martiaux mixtes. Il combat dans la catégorie des poids lourds de l'Ultimate Fighting Championship dont il est le champion depuis le 20 septembre 2026.",118,"fr:Ciryl_Gane","c:5/5f/UFC_Freedom_250%2C_the_mixed_martial_arts_event_produced_by_the_Ultimate_Fighting_Championship%2C_Sunday%2C_June_14%2C_2026%2C_in_the_Grand_Foyer_of_the_White_House_-_64%28cropped%29.jpg",{"cats":["sports","combat"]}],["Q5162259",94,"mma","Conor McGregor","E","Conor Anthony McGregor, né le 14 juillet 1988 à Dublin, est un pratiquant irlandais d'arts martiaux mixtes. Surnommé The Notorious, il est ancien champion des catégories poids plumes et poids légers de l'Ultimate Fighting Championship. Il fut aussi champion des catégories poids plumes et poids légers du Cage Warriors Fighting Championship.","Conor Anthony McGregor, né le 14 juillet 1988 à Dublin, est un pratiquant irlandais d'arts martiaux mixtes.","fr:Conor_McGregor","c:d/d9/Conor_McGregor_in_2015.jpg",{"cats":["sports","combat"]}],["Q205953",95,"mma","Fedor Emelianenko","R","Fedor Vladimirovitch Emelianenko, né le 28 septembre 1976 à Roubijne en RSS d'Ukraine, est un champion russe de sambo et d'arts martiaux mixtes, anciennement sous contrat avec le Bellator MMA et retraité depuis le 5 février 2023.",117,"fr:Fedor_Emelianenko","c:d/d8/Fedor_Emelianenko_Dec_2015.jpg",{"cats":["sports","combat"]}],["Q23883298",96,"mma","Francis Ngannou","R","Francis Ngannou, né le 5 septembre 1986 à Batié au Cameroun, est un pratiquant camerounais d'arts martiaux mixtes et de boxe professionnelle.",119,"fr:Francis_Ngannou","c:5/55/Francis_Ngannou_2023_%28cropped%29.png",{"cats":["sports","combat"]}],["Q356271",97,"mma","Georges Saint-Pierre","R","Georges Saint-Pierre, né le 19 mai 1981 à Saint-Isidore au Québec, est un pratiquant québécois d'arts martiaux mixtes.",null,"fr:Georges_Saint-Pierre","c:e/eb/2021_-_Centre_Stage_DG4_5765_%2851654942080%29_%28cropped%29.jpg",{"cats":["sports","combat"]}],["Q18637676",98,"mma","Islam Makhachev","L","Islam Ramazanovitch Makhachev, né le 27 octobre 1991 à Makhatchkala, est un pratiquant russe d'arts martiaux mixtes. Il est d'origine daghestanaise et d’ethnie lak.","Islam Ramazanovitch Makhachev, né le 27 octobre 1991 à Makhatchkala, est un pratiquant russe d'arts martiaux mixtes.","fr:Islam_Makhachev","c:a/ac/Islam_Makhachev_2022_UFC_belt.png",{"cats":["sports","combat"]}],["Q27050195",99,"mma","Israel Adesanya","R","Israel Adesanya né le 22 juillet 1989 à Lagos, est un pratiquant nigérian naturalisé néo-zélandais d'arts martiaux mixtes et ancien boxeur et kick-boxeur. Il combat actuellement dans la catégorie des poids moyens de l'Ultimate Fighting Championship.",114,"fr:Israel_Adesanya","c:1/12/Israel_Adesanya_at_UFC_230.jpg",{"cats":["sports","combat"]}],["Q285450",100,"mma","Jon Jones","E","Jonathan Dwight Jones plus connu sous le nom de Jon Jones, né le 19 juillet 1987 à Rochester, est un pratiquant américain d'arts martiaux mixtes.",111,"fr:Jon_Jones_(MMA)","c:3/36/JonBonesJones.jpg",{"cats":["sports","combat"]}],["Q3526023",101,"mma","Khabib Nurmagomedov","E","Khabib Abdulmanapovitch Nurmagomedov, né le 20 septembre 1988 à Sildi, est un pratiquant russe d'arts martiaux mixtes actif de 2008 à 2020. Il est d'origine daghestanaise et d’ethnie avar. Il est considéré comme l'un des meilleurs combattants de l'histoire du MMA et a été introduit au Hall of Fame de l'UFC le 30 juin 2022.",117,"fr:Khabib_Nurmagomedov","c:3/34/Khabib_nurmagomedov.jpg",{"cats":["sports","combat"]}],["Q76476288",102,"mma","Khamzat Chimaev","E","Khamzat Khizarovitch Chimaev, né le 1er mai 1994 à Beno-Yurt en République tchétchène d'Itchkérie, est un combattant d'arts martiaux mixtes russo-émirien et ancien lutteur professionnel. Il combat dans la catégorie des poids moyens à l'Ultimate Fighting Championship.",116,"fr:Khamzat_Chimaev","c:b/b8/Khamzat_Chimaev_2022.png",{"cats":["sports","combat"]}],["Q354790",103,"mma","Mirko Filipović","PC","Mirko Filipović, né le 10 septembre 1974 à Vinkovci, est un kick-boxeur et pratiquant d'arts martiaux mixtes croate, par ailleurs homme politique croate durant un mandat.",116,"fr:Mirko_Filipović","c:2/23/Mirko_Cro_Cop.png",{"cats":["sports","combat"]}],["Q352733",104,"mma","Randy Couture","PC","Randy Duane Couture, né le 22 juin 1963 à Lynnwood, est un ancien pratiquant de lutte gréco-romaine et un combattant d'arts martiaux mixtes. Il faisait partie de la Team Quest, une équipe de combattants basée à Gresham avant de créer son lieu d'entraînement.",116,"fr:Randy_Couture","c:7/73/Randy_Couture_by_Gage_Skidmore_2.jpg",{"cats":["sports","combat"]}],["Q573463",106,"boxe","Anthony Joshua","L","Anthony Joshua, né le 15 octobre 1989 à Watford, est un boxeur britannique.",null,"fr:Anthony_Joshua","c:2/2b/Anthony_Joshua_2017.png",{"cats":["sports","combat"]}],["Q2117769",107,"boxe","Canelo Álvarez","L","Canelo Álvarez, de son vrai nom Santos Saúl Álvarez Barragán, né le 18 juillet 1990 à Guadalajara est un boxeur professionnel mexicain.",111,"fr:Canelo_Álvarez","c:8/82/Sa%C3%BAl_%C3%81lvarez.png",{"cats":["sports","combat"]}],["Q17425407",108,"boxe","Estelle Mossely","C","Estelle Mossely, née le 19 août 1992 à Créteil, est une boxeuse française qui combat en poids légers. Elle est la première boxeuse française à devenir championne olympique de boxe aux Jeux olympiques d'été de 2016 et la première Française championne du monde en 2016 et en 2019.","Estelle Mossely, née le 19 août 1992 à Créteil, est une boxeuse française qui combat en poids légers.","fr:Estelle_Mossely","c:a/a2/Estelle_Mossely%2C_Championne_Olympique_de_Boxe_-_Zack_en_Roue_Libre_avec_Estelle_Mossely_%28S07E9%29.jpg",{"cats":["sports","combat"]}],["Q318204",109,"boxe","Floyd Mayweather Jr.","E","Floyd Mayweather Jr. est un boxeur américain né le 24 février 1977 à Grand Rapids dans le Michigan. Surnommé Pretty Boy, il est reconnu comme l’un des meilleurs pugilistes de tous les temps, étant demeuré invaincu en plus de 20 ans de carrière professionnelle et 50 combats, mais aussi grâce à ses nombreux titres de champion du monde obtenus dans cinq catégories de poids différentes.","Floyd Mayweather Jr.","fr:Floyd_Mayweather,_Jr.","c:6/68/Floyd_Mayweather%2C_Jr._at_DeWalt_event.jpg",{"cats":["sports","combat"]}],["Q213919",110,"boxe","George Foreman","E","George Foreman, né le 10 janvier 1949 à Marshall et mort le 21 mars 2025 à Houston, est un boxeur américain.",null,"fr:George_Foreman","c:c/cb/George_Foreman_%281973%29.jpg",{"cats":["sports","combat"]}],["Q107711236",111,"boxe","Imane Khelif","C","Imane Khelif, née le 2 mai 1999 à Aïn Sidi Ali, est une boxeuse algérienne, championne olympique des moins de 66 kg en 2024.",118,"fr:Imane_Khelif","c:7/7f/Imane_Khelif_Jeux_panarabes_2023.png",{"cats":["sports","combat"]}],["Q25714026",112,"boxe","Jake Paul","L","Jake Paul, né le 17 janvier 1997 à Cleveland, est un youtubeur, acteur et un boxeur américain.",null,"fr:Jake_Paul","c:0/01/Jake_Paul_%2853116882732%29.jpg",{"cats":["sports","videastes_int","combat"]}],["Q102301",113,"boxe","Joe Frazier","R","Joseph William Frazier né le 12 janvier 1944 à Beaufort en Caroline du Sud et mort le 7 novembre 2011 à Philadelphie en Pennsylvanie, est un boxeur américain des années 1960 et 1970. Il est en son temps le plus grand rival de Mohamed Ali, qu'il est le premier à battre, le 8 mars 1971, au Madison Square Garden.",119,"fr:Joe_Frazier","c:d/d0/Joe_Frazier_studio_portrait.jpg",{"cats":["sports","combat"]}],["Q273206",114,"boxe","Joe Louis","PC","Joseph Louis Barrow, connu sous le nom de Joe Louis, est un boxeur américain né le 13 mai 1914 à LaFayette et mort le 12 avril 1981 à Las Vegas.",117,"fr:Joe_Louis","c:3/30/Joe_Louis_by_van_Vechten.jpg",{"cats":["sports","combat"]}],["Q328951",116,"boxe","Mary Kom","R","Mangte Chungneijang Mary Kom, dite Mary Kom, est une boxeuse amateure indienne, née le 1er mars 1983 à Kangathei dans l’État de Manipur. Elle est la seule boxeuse indienne à avoir remporté une médaille d’or aux Jeux asiatiques ainsi qu'une médaille aux Jeux olympiques. Surnommée « Magnificient Mary », elle est mariée à K Onler Kom, et est mère de trois enfants, dont des jumeaux: Khupneivar Kom, Rechungvar Kom et le dernier né, Prince Chungthanglen Kom.",117,"fr:Mary_Kom","c:d/dc/Mary_Kom_-_British_High_Commission%2C_Delhi%2C_27_July_2011.jpg",{"cats":["sports","combat"]}],["Q79031",117,"boxe","Mike Tyson","M","Michael Gerard Tyson, dit Mike Tyson, né le 30 juin 1966 à New York dans l'arrondissement de Brooklyn, est un boxeur américain.",116,"fr:Mike_Tyson","c:e/ee/Mike_Tyson_Photo_Op_GalaxyCon_Austin_2023.jpg",{"cats":["sports","combat"]}],["Q36107",118,"boxe","Mohamed Ali","M","Muhammad Ali — en français, plus souvent écrit Mohamed Ali — né le 17 janvier 1942 à Louisville dans le Kentucky, appelé Cassius Clay jusqu'en 1964 et mort le 3 juin 2016 à Scottsdale en Arizona, est un boxeur américain évoluant en catégorie poids lourds, considéré comme l'un des plus grands boxeurs de tous les temps, surnommé The Greatest et comme une icône culturelle, à la fois adulée et vilipendée.",113,"fr:Mohamed_Ali","c:8/89/Muhammad_Ali_NYWTS.jpg",{"cats":["sports","combat"]}],["Q938027",119,"boxe","Oleksandr Usyk","L","Oleksandr Oleksandrovych Usyk, né le 17 janvier 1987 à Simferopol, en RSS d'Ukraine, est un boxeur ukrainien. Champion du monde unifié dans la catégorie poids lourds-légers, il laisse en 2019 ses ceintures vacantes pour combattre en poids lourds et devient également champion du monde unifié WBA, IBF et WBO de cette catégorie en 2021 et WBC en 2024 ce qui fait de lui le troisième boxeur à détenir les quatre ceintures dans deux catégories différentes.","Oleksandr Oleksandrovych Usyk, né le 17 janvier 1987 à Simferopol, en RSS d'Ukraine, est un boxeur ukrainien.","fr:Oleksandr_Usyk","c:0/08/2022_-_SportsTrade_stage_SM6_0844_%2852472615761%29.jpg",{"cats":["sports","combat"]}],["Q188362",120,"boxe","Rocky Marciano","R","Rocky Marciano, de son vrai nom Rocco Francis Marchegiano, né le 1er septembre 1923 et mort le 31 août 1969, est un boxeur américain. Son surnom a été repris pour nommer le personnage de fiction Rocky Balboa de la série de films Rocky avec Sylvester Stallone.",115,"fr:Rocky_Marciano","c:1/1c/Rocky_Marciano_-_10_April_1954_-_St._Paul_Armory_Wrestling_Program.jpg",{"cats":["sports","combat"]}],["Q335798",121,"boxe","Sugar Ray Leonard","PC","Ray Charles Leonard, connu sous le nom de \" Sugar \" Ray Leonard est un ancien boxeur professionnel américain né le 17 mai 1956 à Wilmington, en Caroline du Nord. De 1977 à 1997, il enregistre un palmarès impressionnant en remportant des titres mondiaux dans cinq catégories de poids différentes et le championnat linéaire en trois catégories de poids différentes.",117,"fr:Sugar_Ray_Leonard","c:4/4f/Sugar_Ray_Leonard.jpg",{"cats":["sports","combat"]}],["Q316706",122,"boxe","Sugar Ray Robinson","R","Walker Smith Jr. dit Sugar Ray Robinson est un boxeur américain professionnel s'étant illustré entre les années 1940 et les années 1960, et souvent cité à ce titre parmi les plus illustres pugilistes de l'histoire. Ses prestations sur le ring ont incité nombre d'observateurs à créer le classement pound for pound, permettant ainsi de comparer les boxeurs au-delà des différences de catégories de poids. Il est intronisé à l'International Boxing Hall of Fame dès sa création en 1990.","Walker Smith Jr.","fr:Sugar_Ray_Robinson","c:d/d8/Sugar_Ray_Robinson_1965_%28cropped%29.jpg",{"cats":["sports","combat"]}],["Q2029136",123,"boxe","Tony Yoka","C","Tony Yoka, né le 28 avril 1992 à Paris, est un boxeur français notamment champion de France, du monde et olympique.",null,"fr:Tony_Yoka","c:d/d6/Tony_Yoka_%28FRA%29_Rio_2016.jpg",{"cats":["sports","combat"]}],["Q1000592",124,"boxe","Tyson Fury","E","Tyson Luke Fury, né le 12 août 1988 à Wythenshawe en Angleterre, est un boxeur britannique.",null,"fr:Tyson_Fury","c:8/8d/Tyson_Fury_at_Place_Bell%2C_Laval_Quebec%2C_Canada_-_Dec_16_2017_%28cropped%29.jpg",{"cats":["sports","combat"]}],["Q18797",125,"boxe","Wladimir Klitschko","E","Vladimir Klitschko est un boxeur ukrainien, né le 25 mars 1976 à Semipalatinsk en RSS kazakhe.",null,"fr:Wladimir_Klitschko","c:c/cd/Volodymyr_Klychko_%28Vladimir_Klitschko%29_of_Ukraine_at_the_59th_Munich_Security_Conference_in_Munich_on_17_February_2023_-_%28cropped%29.jpg",{"cats":["sports","combat"]}],["Q317422",128,"rugby","Eric Liddell","PC","Eric Liddell est un athlète écossais spécialiste du sprint et un joueur de rugby à XV, né le 16 janvier 1902 à Tianjin et mort le 21 février 1945 à Weifang. Après sa carrière sportive, il a été missionnaire protestant.",118,"fr:Eric_Liddell","c:e/e1/Eric_Liddell.jpg"],["Q52596",142,"athletisme","Abebe Bikila","C","Abebe Bikila, parfois également retranscrit Abébé Bikila, né le 7 août 1932 à Jato et mort le 25 octobre 1973 à Addis-Abeba, est un athlète éthiopien, spécialiste des courses de fond. Premier médaillé olympique éthiopien, il remporte l'épreuve du marathon aux Jeux olympiques de 1960 et 1964.",111,"fr:Abebe_Bikila","c:3/3b/Abebe_Bikila_1968c.jpg"],["Q5799",143,"athletisme","Allyson Felix","C","Allyson Felix, née le 18 novembre 1985 à Los Angeles, Californie, est une athlète américaine, médaillée dans les grands événements sur 100 m, 200 m et 400 m. Elle est ainsi, après Betty Cuthbert, la seconde athlète de l'histoire à être médaillée d'or olympique sur les trois distances du sprint.",119,"fr:Allyson_Felix","c:1/10/AllysonFelixRio2016.jpg"],["Q20740797",144,"athletisme","Armand Duplantis","PC","Armand Duplantis, la plupart du temps surnommé Mondo Duplantis, né le 10 novembre 1999 à Lafayette, est un athlète américano-suédois spécialiste du saut à la perche. Possédant la double nationalité, il choisit de représenter la Suède lors des compétitions internationales. Il établit son premier record du monde avec 6,17 m en février 2020 et l'améliore quatorze autres fois pour le porter à 6,31 m en mars 2026.",114,"fr:Armand_Duplantis","c:d/dd/Armand_Duplantis_DSC02363.jpg"],["Q182747",145,"athletisme","Asafa Powell","C","Asafa Powell, né le 23 novembre 1982 dans la paroisse de Sainte-Catherine en Jamaïque, est un athlète jamaïcain, ancien détenteur du record du monde du 100 mètres et quatrième athlète le plus rapide de l'histoire de la discipline. Il est sacré champion olympique et champion du monde du relais 4 × 100 mètres, mais n'a jamais remporté de titre majeur en individuel.",119,"fr:Asafa_Powell","c:a/ac/Asafa_Powell_com_medalha_de_ouro_no_4_x_100_metros_1039105-19.08.2016_frz-120_%28cropped%29.jpg"],["Q52604",146,"athletisme","Bob Beamon","C","Robert Beamon dit Bob Beamon est un athlète américain, spécialiste du saut en longueur.",null,"fr:Bob_Beamon","c:b/b0/Bob_Beamon_-_50_a%C3%B1os_de_M%C3%A9xico_68_-_25.jpg"],["Q365144",147,"athletisme","Caitlyn Jenner","M","Caitlyn Jenner est une personnalité américaine du monde des médias, née le 28 octobre 1949 à Mount Kisco dans l'État de New York.",119,"fr:Caitlyn_Jenner","c:9/94/Caitlyn_Jenner.jpeg"],["Q131237",148,"athletisme","Carl Lewis","PC","Frederick Carlton Lewis, dit Carl Lewis, né à Birmingham le 1er juillet 1961, est un athlète américain. Il a notamment remporté dix médailles olympiques dont neuf en or, ainsi que dix médailles aux championnats du monde d'athlétisme dont huit en or.","Frederick Carlton Lewis, dit Carl Lewis, né à Birmingham le 1er juillet 1961, est un athlète américain.","fr:Carl_Lewis","c:8/81/Save_The_World_Awards_2009_show06_-_Carl_Lewis.jpg"],["Q274636",149,"athletisme","Christophe Lemaitre","C","Christophe Lemaitre, né le 11 juin 1990 à Annecy, est un athlète français spécialiste du sprint, et plus particulièrement du 200 mètres. Actuel détenteur du record de France de la spécialité, en 19 s 80, il est médaillé de bronze sur la distance en 2011 à Daegu, et médaillé de bronze aux Jeux Olympiques de Rio en 2016. Il est le seul sprinteur Français de l'histoire médaillé en individuel lors des Championnats du monde et des Jeux Olympiques.",104,"fr:Christophe_Lemaitre","c:2/28/Christophe_Lemaitre_Rio_2016.jpg"],["Q9124",150,"athletisme","Eliud Kipchoge","R","Eliud Kipchoge, né le 5 novembre 1984 à Kapsisiywa, est un athlète kényan spécialiste des courses de fond.",null,"fr:Eliud_Kipchoge","c:f/fc/Eliud_Kipchoge_in_Berlin_-_2015_%28cropped%29.jpg"],["Q52589",151,"athletisme","Emil Zátopek","C","Emil Zátopek, né le 19 septembre 1922 à Kopřivnice et mort le 22 novembre 2000 à Prague, est un athlète tchécoslovaque spécialiste des courses de fond, du 5 000 mètres au marathon.",118,"fr:Emil_Zátopek","c:3/38/Emil_Z%C3%A1topek_redux.jpg"],["Q69424112",152,"athletisme","Femke Bol","C","Femke Broeders-Bol, née Femke Bol le 23 février 2000 à Amersfoort, est une athlète néerlandaise spécialiste du 400 mètres et du 400 mètres haies au début de sa carrière, avant de se spécialiser sur le 800 mètres.",114,"fr:Femke_Broeders-Bol","c:a/af/Femke_Bol_240823_Budapest_2023.jpg"],["Q31082",153,"athletisme","Florence Griffith-Joyner","PC","Florence Griffith-Joyner, née Delorez Florence Griffith le 21 décembre 1959 à Los Angeles et morte le 21 septembre 1998 à Mission Viejo, est une athlète américaine, spécialiste des épreuves de sprint. Elle détient depuis 1988 les records du monde hors normes du 100 mètres — 10 s 49 lors des sélections olympiques américaines le 16 juillet 1988 à Indianapolis — et du 200 mètres — 21 s 34 en finale des Jeux olympiques de Séoul le 29 septembre de la même année.",119,"fr:Florence_Griffith-Joyner","c:8/89/Florence_Griffith_Joyner2.jpg"],["Q171500",154,"athletisme","Haile Gebrselassie","C","Haile Gebrselassie est un coureur de fond éthiopien, né le 18 avril 1973 dans l'Arsi. Il a remporté deux médailles d'or aux Jeux olympiques et huit aux championnats du monde d'athlétisme sur des distances allant du 1 500 mètres au 10 000 mètres.","Haile Gebrselassie est un coureur de fond éthiopien, né le 18 avril 1973 dans l'Arsi.","fr:Haile_Gebrselassie","c:5/5a/Haile_Gebrselassie_at_Vienna_City_Marathon_2011.jpg"],["Q209390",155,"athletisme","Jackie Joyner-Kersee","C","Jacqueline \"Jackie\" Joyner-Kersee est une athlète américaine, spécialiste des épreuves combinées et du saut en longueur.",null,"fr:Jackie_Joyner-Kersee","c:3/31/Jackie_Joyner-Kersee_%282%29_%28cropped%29.jpg"],["Q19974493",156,"athletisme","Jakob Ingebrigtsen","C","Jakob Ingebrigtsen, né le 19 septembre 2000 à Sandnes, est un athlète norvégien, spécialiste des courses de demi-fond et fond. Recordman du monde du 3 000 mètres en 7 min 17 s 55, il est champion olympique en 2021 à Tokyo sur 1 500 mètres, et à Paris 2024, sur 5 000 mètres.",117,"fr:Jakob_Ingebrigtsen","c:b/b5/Jacob_Ingebrigtsen_Istanbul_2023_%28cropped%29.jpg"],["Q52651",157,"athletisme","Jesse Owens","PC","James Cleveland Owens dit Jesse Owens, né le 12 septembre 1913 à Oakville et mort le 31 mars 1980 à Tucson, est un athlète américain considéré comme le premier sportif noir de renommée internationale, et comme le meilleur sprinteur de l'entre-deux-guerres.",114,"fr:Jesse_Owens","c:1/19/Jesse_Owens_1936.jpg"],["Q221482",158,"athletisme","Jim Thorpe","R","James Francis Thorpe, dit Jim Thorpe, né le 27 mai 1887 à Prague dans l'Oklahoma et mort le 28 mars 1953 à Lomita en Californie, est un joueur et un dirigeant de football américain, un joueur de baseball et de basket-ball, un athlète et un acteur américain d'ascendance blanche et amérindienne.",116,"fr:Jim_Thorpe","c:e/ec/Jim_Thorpe_Canton_Bulldogs_1915-20.png"],["Q1652",159,"athletisme","Justin Gatlin","C","Justin Alexander Gatlin est un athlète américain, spécialiste des épreuves de sprint.",null,"fr:Justin_Gatlin","c:3/3e/Justin_Gatlin_Rio_100m_final_2016b-cr.jpg"],["Q115601844",160,"athletisme","Kelvin Kiptum","PC","Kelvin Kiptum, né le 2 décembre 1999 à Eldoret et mort le 11 février 2024 à Kaptagat, est un athlète kenyan, spécialiste des courses de fond. Il détenait le record du monde du marathon en 2 h 0 min 35 s jusqu'au 26 avril 2026, battu par le Kenyan Sabastian Sawe, qui devient le premier homme de l’histoire à terminer un marathon en moins de deux heures.",108,"fr:Kelvin_Kiptum","c:d/d0/Kelvin_Kiptum_%28KEN%29_2023.jpg"],["Q9119",161,"athletisme","Kenenisa Bekele","C","Kenenisa Bekele Beyecha, né le 13 juin 1982 à Bekoji, est un athlète éthiopien, spécialiste des courses de fond.",null,"fr:Kenenisa_Bekele","c:8/8b/Kenenisa_Bekele_2014_Paris_Marathon_t084551.jpg"],["Q3195752",162,"athletisme","Kevin Mayer","C","Kevin Mayer, né le 10 février 1992 à Argenteuil, est un athlète français spécialiste des épreuves combinées. Il détient, depuis le 16 septembre 2018, le record du monde du décathlon avec 9 126 points, ce qui fait de lui le seul Français encore recordman du monde d'une épreuve d'athlétisme, avec Yohann Diniz sur 50 kilomètres marche.","Kevin Mayer, né le 10 février 1992 à Argenteuil, est un athlète français spécialiste des épreuves combinées.","fr:Kevin_Mayer","c:2/22/Kevin_Mayer_%28cropped%29_en_2019.jpg"],["Q438670",163,"athletisme","Kévin Borlée","C","Kévin Borlée, né le 22 février 1988 à Woluwe-Saint-Lambert, est un sprinteur belge, spécialiste du 400 m. Il remporte des médailles d'or dans les championnats d'Europe, championnats de Belgique et dans les championnats du monde en salle. À cela s'ajoutent plusieurs médailles de bronze lors des championnats du monde d'athlétisme. De 2008 à 2024, il participe à de nombreuses finales des jeux olympiques dans les disciplines du 400 m, 4 x 400 m masculin et 4 x 400 m mixte.","Kévin Borlée, né le 22 février 1988 à Woluwe-Saint-Lambert, est un sprinteur belge, spécialiste du 400 m.","fr:Kévin_Borlée","c:b/b6/BKAC2781_kevin_borl%C3%A9e_400m_%2842411806155%29.jpg"],["Q228808",164,"athletisme","Marie-José Pérec","C","Marie-José Pérec, née le 9 mai 1968 à Basse-Terre en Guadeloupe, est une athlète française. Elle est la seule Française triple championne olympique d'athlétisme: en 1992 aux Jeux de Barcelone et deux fois aux Jeux d'Atlanta en 1996.","Marie-José Pérec, née le 9 mai 1968 à Basse-Terre en Guadeloupe, est une athlète française.","fr:Marie-José_Pérec","c:0/04/Marie-Jos%C3%A9_P%C3%A9rec_Cannes_2016.jpg"],["Q190924",165,"athletisme","Michael Johnson","C","Michael Duane Johnson est un athlète américain, né le 13 septembre 1967 à Dallas, au Texas. Il est considéré comme l'un des plus grands sprinteurs de tous les temps, avec quatre titres olympiques et huit titres mondiaux. Il a aussi détenu pendant dix-sept ans le record du monde du 400 m et pendant douze ans le record du monde du 200 m.","Michael Duane Johnson est un athlète américain, né le 13 septembre 1967 à Dallas, au Texas.","fr:Michael_Johnson","c:7/70/Michael_Johnson_1995.jpg"],["Q1671",166,"athletisme","Mohamed Farah","PC","Sir Mohamed Farah, très souvent surnommé Mo Farah, est un athlète britannique d'origine somalienne, spécialiste des courses de fond et de demi-fond.",115,"fr:Mohamed_Farah","c:7/71/MoPodiumRio2016.png"],["Q24955843",168,"athletisme","Neeraj Chopra","C","Neeraj Chopra est un athlète indien, spécialiste du lancer du javelot.",null,"fr:Neeraj_Chopra","c:f/fb/Neeraj_Chopra_Olympic_gold_medalist.jpg"],["Q15989263",169,"athletisme","Noah Lyles","C","Noah Lyles, né le 18 juillet 1997 à Gainesville en Floride, est un athlète américain, spécialiste des épreuves de sprint.",113,"fr:Noah_Lyles","c:3/3d/Paris_2024_Noah_Lyles_interview_after_winning_the_100m_final.png"],["Q201377",170,"athletisme","Oscar Pistorius","R","Oscar Pistorius, né le 22 novembre 1986 à Johannesbourg, est un athlète sud-africain né sans péronés et amputé sous le genou, à la moitié du tibia précisément, à l'âge de 11 mois, spécialisé dans le sprint. Il est le meurtrier condamné de sa compagne, la mannequin Reeva Steenkamp.",118,"fr:Oscar_Pistorius","c:2/2f/Oscar_Pistorius_2_Daegu_2011.jpg"],["Q101942",171,"athletisme","Paavo Nurmi","C","Paavo Johannes Nurmi est un athlète finlandais né le 13 juin 1897 à Turku et mort le 2 octobre 1973 à Helsinki, en Finlande. Poursuivant la tradition du fond finlandais, il règne sur le plan mondial durant près de quatorze ans. Lors de sa carrière, il établit vingt-deux records du monde, du 1 500 m au 20 000 m, et remporte douze médailles lors des Jeux olympiques, dont neuf titres, devenant ainsi l'athlète le plus médaillé de ce sport. Il est par la suite rejoint par Carl Lewis.",114,"fr:Paavo_Nurmi","c:c/c4/Paavo_Nurmi_in_USA_%281925%29.jpg"],["Q1742",172,"athletisme","Renaud Lavillenie","C","Renaud Lavillenie, né le 18 septembre 1986 à Barbezieux-Saint-Hilaire, est un athlète français, spécialiste du saut à la perche, champion olympique à Londres en 2012.",117,"fr:Renaud_Lavillenie","c:9/9e/Renaud_Lavillenie_at_the_2026_Wanda_Diamond_League_Athletissima_athletics_competition._06.jpg",{"cats":["sports","moto"]}],["Q188502",173,"athletisme","Sebastian Coe","C","Sebastian Newbold Coe, baron Coe de Ranmore, né le 29 septembre 1956 à Chiswick, Londres, est un athlète et homme politique britannique. Il est double champion olympique du 1500 m, organisateur des Jeux olympiques de Londres 2012 et président de World Athletics à compter du 31 août 2015.",113,"fr:Sebastian_Coe","c:7/74/Lord_Coe_-_World_Economic_Forum_Annual_Meeting_2012_cropped.jpg"],["Q184556",174,"athletisme","Sergueï Bubka","C","Sergueï Bubka, est un athlète ukrainien, spécialiste du saut à la perche, né le 4 décembre 1963 à Louhansk en URSS. Il est nommé Héros d'Ukraine par le président Leonid Koutchma le 4 février 2001.","Sergueï Bubka, est un athlète ukrainien, spécialiste du saut à la perche, né le 4 décembre 1963 à Louhansk en URSS.","fr:Sergueï_Bubka","c:7/7e/Sergey_Bubka_2013.jpg"],["Q5793",175,"athletisme","Shelly-Ann Fraser-Pryce","C","Shelly-Ann Fraser-Pryce, née le 27 décembre 1986 à Kingston, est une athlète jamaïcaine, spécialiste des épreuves de sprint qui totalise huit médailles olympiques et dix titres mondiaux. Elle est considérée comme une des plus grandes sprinteuses de tous les temps.",116,"fr:Shelly-Ann_Fraser-Pryce","c:9/9e/Shelly_Fraser_Oregon_22.jpg"],["Q14855644",176,"athletisme","Sifan Hassan","C","Sifan Hassan, née le 1er janvier 1993 à Adama est une athlète éthiopienne, naturalisée néerlandaise en 2013. Elle est spécialiste des courses de demi-fond et de fond.","Sifan Hassan, née le 1er janvier 1993 à Adama est une athlète éthiopienne, naturalisée néerlandaise en 2013.","fr:Sifan_Hassan","c:d/d4/Sifan_Hassan_Budapest_2023.jpg"],["Q232008",177,"athletisme","Stefka Kostadinova","C","Stefka Kostadinova, née le 25 mars 1965 à Plovdiv, est une athlète bulgare pratiquant le saut en hauteur. Elle a détenu le record du monde du saut en hauteur entre 1987 et 2024 avec une marque à 2,09 m.","Stefka Kostadinova, née le 25 mars 1965 à Plovdiv, est une athlète bulgare pratiquant le saut en hauteur.","fr:Stefka_Kostadinova","c:9/95/Stefka_Kostadinova.JPG"],["Q1189",178,"athletisme","Usain Bolt","E","Usain Bolt est un athlète jamaïcain spécialiste des épreuves de sprint, né le 21 août 1986 dans la paroisse de Trelawny. Il est généralement considéré comme le plus grand sprinteur de tous les temps.","Usain Bolt est un athlète jamaïcain spécialiste des épreuves de sprint, né le 21 août 1986 dans la paroisse de Trelawny.","fr:Usain_Bolt","c:3/3f/Usain_Bolt_Rio_100m_final_2016i-cr.jpg"],["Q6319",179,"athletisme","Yelena Isinbayeva","C","Yelena Gadzhievna Isinbayeva née le 3 juin 1982 à Volgograd est une athlète russe pratiquant le saut à la perche. Double championne olympique, aux Jeux d'Athènes 2004 et de Pékin 2008, elle est également triple championne du monde et championne d'Europe. Elle est l'actuelle détentrice du record du monde du saut à la perche féminin, avec 5,06 mètres franchis en plein air à Zurich en 2009.","Yelena Gadzhievna Isinbayeva née le 3 juin 1982 à Volgograd est une athlète russe pratiquant le saut à la perche.","fr:Yelena_Isinbayeva","c:2/28/%D0%95%D0%BB%D0%B5%D0%BD%D0%B0_%D0%98%D1%81%D0%B8%D0%BD%D0%B1%D0%B0%D0%B5%D0%B2_%D0%B2_%D0%9A%D1%80%D0%B5%D0%BC%D0%BB%D0%B5.jpg"],["Q297477",180,"natation","Alain Bernard","C","Alain Bernard, né le 1er mai 1983 à Aubagne, est un nageur français. Licencié au Cercle des nageurs d'Antibes, entraîné par Denis Auguin, sa carrière internationale au plus haut niveau s'étend de 2005 à 2012.","Alain Bernard, né le 1er mai 1983 à Aubagne, est un nageur français.","fr:Alain_Bernard","c:d/d7/Alain_Bernard_%28cropped%29.jpg"],["Q137579",181,"natation","Camille Muffat","C","Camille Muffat, née le 28 octobre 1989 à Nice et morte le 9 mars 2015 à Villa Castelli en Argentine, est une nageuse française.",116,"fr:Camille_Muffat","c:8/85/Camille_Muffat.jpg"],["Q232395",182,"natation","Esther Williams","PC","Esther Jane Williams, née le 8 août 1921 à Inglewood et morte le 6 juin 2013 à Beverly Hills, est une nageuse de compétition, une actrice et une chanteuse américaine.",112,"fr:Esther_Williams","c:5/56/Esther_Williams_-_portrait.jpg"],["Q137575",183,"natation","Florent Manaudou","C","Florent Manaudou, né le 12 novembre 1990 à Villeurbanne, est un nageur français spécialiste des épreuves de nage libre. Il est actuellement licencié au Cercle des nageurs de Marseille. Entre 2012 et 2024, il remporte six médailles aux Jeux olympiques.","Florent Manaudou, né le 12 novembre 1990 à Villeurbanne, est un nageur français spécialiste des épreuves de nage libre.","fr:Florent_Manaudou","c:a/ae/Florent_Manaudou_Kazan_2015.jpg"],["Q185044",184,"natation","Ian Thorpe","C","Ian James Thorpe, médaillé de l'ordre d'Australie, né le 13 octobre 1982 à Sydney, est un nageur australien. Il est, avec cinq titres olympiques, l'Australien ayant remporté le plus de médailles d'or olympiques chez les hommes. De plus, ses onze médailles d'or aux championnats du monde en font le deuxième nageur le plus titré dans cette compétition, derrière l'Américain Michael Phelps.","Ian James Thorpe, médaillé de l'ordre d'Australie, né le 13 octobre 1982 à Sydney, est un nageur australien.","fr:Ian_Thorpe","c:2/27/Ian_Thorpe_2012.jpg"],["Q151284",185,"natation","Johnny Weissmuller","PC","Johnny Weissmuller, né János Péter Weissmüller le 2 juin 1904 à Freidorf en Autriche-Hongrie et mort le 20 janvier 1984 à Acapulco au Mexique, est un nageur olympique américain, cinq fois médaillé d'or aux Jeux olympiques et longtemps recordman du 100 m nage libre, ainsi qu'un acteur de cinéma, célèbre pour avoir incarné le personnage de Tarzan à douze reprises durant les années 1930 et 1940.",119,"fr:Johnny_Weissmuller","c:6/6e/Johny_Weissmuller-publicity.JPG"],["Q137374",186,"natation","Katie Ledecky","PC","Katie Ledecky, de son nom complet Kathleen Genevieve Ledecky, née le 17 mars 1997, est une nageuse américaine spécialiste des épreuves de longue distance en nage libre. Championne olympique à neuf reprises et vingt-trois fois championne du monde en grand bassin depuis 2012, elle est la seule nageuse de l'histoire à avoir remporté quatre titres individuels lors des mêmes championnats du monde, à Kazan en 2015. Elle est également l'actuelle détentrice des records du monde sur 800 m et 1 500 m nage libre.",109,"fr:Katie_Ledecky","c:d/d2/Katie_Ledecky_2016d.jpg"],["Q274009",187,"natation","Kirsty Coventry","C","Kirsty Leigh Coventry, née le 16 septembre 1983 à Harare, est une championne olympique zimbabwéenne de natation, femme politique et la première femme élue à la présidence du Comité international olympique.",118,"fr:Kirsty_Coventry","c:0/08/2018-10-17_Boxing_lightweight_Boys%27_%E2%80%9360_kg_at_2018_Summer_Youth_Olympics_%E2%80%93_Victory_ceremony_%28Martin_Rulsch%29_2.jpg"],["Q45659",188,"natation","Laure Manaudou","C","Laure Manaudou, née le 9 octobre 1986 à Villeurbanne, est une nageuse française pratiquant les quatre nages ayant obtenu des résultats nationaux et internationaux dans la quasi-totalité des distances de compétition: 50 m, 100 m, 200 m, 400 m, 800 m et 1 500 m. Lorsqu'elle s'impose à 17 ans sur 400 m nage libre aux Jeux olympiques d'Athènes, le 15 août 2004, elle est la deuxième championne olympique française de natation après Jean Boiteux à Helsinki en 1952.",113,"fr:Laure_Manaudou","c:8/8d/Image_Laure_Manaudou.png"],["Q63246909",189,"natation","Léon Marchand","C","Léon Marchand, né le 17 mai 2002 à Toulouse, est un nageur français spécialiste des épreuves quatre nages, brasse et papillon. Il est l'athlète le plus décoré des Jeux olympiques de Paris 2024 avec quatre médailles d'or, ce qui fait de lui le sportif français le plus titré sur une édition des Jeux. Il détient par ailleurs les records du monde des 200 m et 400 m quatre nages.",116,"fr:Léon_Marchand","c:f/f0/L%C3%A9on_Marchand%2C_2023_Pac-12_Championships%2C_400_yard_individual_medley_preliminaries_-_3_March_2023.jpg"],["Q180748",190,"natation","Mark Spitz","C","Mark Andrew Spitz, né le 10 février 1950 à Modesto, est un nageur américain. Il a gagné sept médailles d’or lors des Jeux olympiques d'été de 1972 à Munich. Seul Michael Phelps a fait mieux en gagnant huit médailles d'or lors des Jeux olympiques d'été de 2008 à Pékin. Mark Spitz avait également participé aux Jeux olympiques d'été de 1968 à Mexico, remportant quatre médailles. Entre 1968 et 1972, il fut nageur à l’université de l'Indiana.","Mark Andrew Spitz, né le 10 février 1950 à Modesto, est un nageur américain.","fr:Mark_Spitz","c:0/03/Mark_Spitz.jpg"],["Q39562",191,"natation","Michael Phelps","R","Michael Phelps, né le 30 juin 1985 à Towson, est un nageur américain.",null,"fr:Michael_Phelps","c:c/c7/Michael_Phelps_Rio_Olympics_2016.jpg"],["Q201517",192,"natation","Ryan Lochte","C","Ryan Lochte, né le 3 août 1984 à Canandaigua, est un nageur américain spécialiste des épreuves de dos et quatre nages.",null,"fr:Ryan_Lochte","c:7/79/Ryan_Lochte_at_2013_Zajac.jpg"],["Q213125",193,"natation","Rūta Meilutytė","C","Rūta Meilutytė, née le 19 mars 1997 à Kaunas, est une nageuse lituanienne spécialiste de brasse. Championne olympique en 2012 du 100 m brasse, elle détient en 2022 les records du monde en petit bassin du 50 m et du 100 m brasse ainsi que le record d'Europe en grand bassin sur 100 m brasse.","Rūta Meilutytė, née le 19 mars 1997 à Kaunas, est une nageuse lituanienne spécialiste de brasse.","fr:Rūta_Meilutytė","c:b/b5/R%C5%ABta_Meilutyt%C4%97_portrait.jpg"],["Q232711",194,"golf","Annika Sörenstam","C","Annika Sörenstam, née le 9 octobre 1970 à Bro, est une golfeuse professionnelle suédoise dont les performances la placent comme l'une des meilleures golfeuses de l'histoire. Avant de se retirer sportivement en 2008, elle a remporté quatre-vingt-dix tournois en tant que professionnelle, faisant d'elle la golfeuse la plus victorieuse de l'histoire. Elle a remporté soixante-douze tournois sur le circuit de la LPGA dont dix tournois majeurs et dix-huit autres tournois dans le monde.",113,"fr:Annika_Sörenstam","c:9/9f/2008_LPGA_Championship_-_Annika_Sorenstam_tee_shot.jpg"],["Q9434",195,"golf","Arnold Palmer","PC","Arnold Daniel Palmer, né le 10 septembre 1929 à Latrobe en Pennsylvanie et mort le 25 septembre 2016 à Pittsburgh en Pennsylvanie, a été un joueur de golf professionnel américain qui a remporté de nombreux tournois à partir de 1955.",116,"fr:Arnold_Palmer","c:9/9a/Arnold_Palmer_%28cropped%29.jpg"],["Q9424",196,"golf","Jack Nicklaus","PC","Jack William Nicklaus, né le 21 janvier 1940 à Columbus, aussi connu sous le surnom The Golden Bear, a été une figure majeure du golf professionnel, d'abord sur le circuit PGA depuis les années 1960 jusqu'à la fin des années 1980, puis sur le circuit senior de la fin des années 1980 jusqu'à la fin des années 1990, et est considéré comme l'un des meilleurs golfeurs de tous les temps.",117,"fr:Jack_Nicklaus","c:6/68/Jack_Nicklaus_2019_Jenkins_Medal_Awards_%28cropped%29.jpg"],["Q270784",197,"golf","Margaret Abbott","C","Margaret Abbott est une golfeuse américaine.",null,"fr:Margaret_Abbott","c:d/d2/Margaret-abbott-gold-medal-1900-golf.jpg"],["Q380613",198,"golf","Rory McIlroy","PC","Rory McIlroy, né le 4 mai 1989 à Holywood, est un golfeur professionnel nord-irlandais, ancien numéro 1 mondial et l’un des joueurs les plus marquants de sa génération. Passé professionnel en 2007 après avoir occupé la première place du classement amateur mondial, il s’impose rapidement sur le circuit européen puis sur le PGA Tour grâce à la puissance et à la précision de son jeu long.",119,"fr:Rory_McIlroy","c:0/02/Rory_McIlroy_Ryder_Cup_2025-195_%28cropped%29.jpg"],["Q30161386",199,"golf","Scottie Scheffler","PC","Scott Scheffler dit Scottie Scheffler, né le 21 juin 1996 à Ridgewood, est un golfeur professionnel américain, actuel numéro 1 mondial. Vainqueur de quatre tournois majeurs — le Masters en 2022 et 2024 ainsi que le Championnat de la PGA en 2023 et 2025 — et champion olympique aux Jeux olympiques de Paris 2024, il est considéré comme le joueur dominant du golf mondial au milieu des années 2020.",117,"fr:Scottie_Scheffler","c:e/ef/Scottie_Scheffler_Ryder_Cup_2025_%28cropped%29.jpg"],["Q272190",200,"golf","Severiano Ballesteros","C","Severiano Ballesteros Sota dit Seve Ballesteros, né à Pedreña le 9 avril 1957 et mort le 7 mai 2011 dans sa villa de Pedreña est un golfeur espagnol.",116,"fr:Severiano_Ballesteros","c:6/60/Seve_Ballesteros_2006-07-19.jpg"],["Q10993",201,"golf","Tiger Woods","R","Eldrick Tont Woods, plus connu sous le nom de Tiger Woods, né le 30 décembre 1975 à Cypress, est un golfeur américain.",null,"fr:Tiger_Woods","c:3/3e/Tiger_Woods_in_May_2019.jpg"],["Q2975621",202,"judo","Clarisse Agbegnenou","C","Clarisse Agbegnenou est une judokate française, née le 25 octobre 1992 à Rennes.",null,"fr:Clarisse_Agbegnenou","c:a/ad/Clarisse_Agbegnenou.jpeg"],["Q725694",203,"judo","David Douillet","C","David Douillet, né le 17 février 1969 à Rouen en Seine-Maritime, est un judoka et homme politique français. Il est élu député dans la 12e circonscription des Yvelines de 2009 à 2011 puis de 2012 à 2017. Il fut également ministre des Sports de septembre 2011 à mai 2012.","David Douillet, né le 17 février 1969 à Rouen en Seine-Maritime, est un judoka et homme politique français.","fr:David_Douillet","c:c/c4/UMP_meeting_Paris_regional_elections_2010-03-17_n04.jpg"],["Q467769",204,"judo","Ingrid Berghmans","C","Ingrid Berghmans est une judokate belge née le 24 août 1961 à Koersel. Elle est l'une des sportives les plus récompensées de l'histoire du judo.","Ingrid Berghmans est une judokate belge née le 24 août 1961 à Koersel.","fr:Ingrid_Berghmans","c:2/24/Olympische_Vlam_%28cropped%29.jpg"],["Q190141",205,"judo","Jigorō Kanō","C","Jigorō Kanō, né le 28 octobre 1860 à Préfecture de Hyōgo et mort en mer le 4 mai 1938, est un éducateur japonais, fondateur du judo.",113,"fr:Jigorō_Kanō","c:1/10/Portrait_of_late_Mr._Kano.jpg"],["Q1820096",206,"judo","Majlinda Kelmendi","C","Majlinda Kelmendi, née le 9 mai 1991 à Pejë, est une judokate kosovare en activité évoluant dans la catégorie des moins de 52 kg. Double championne du monde en 2013 et 2014, et championne d'Europe, en 2014 et 2016, elle remporte lors des Jeux olympiques 2016 de Rio de Janeiro le seul titre manquant à son palmarès, l'or olympique.",119,"fr:Majlinda_Kelmendi","c:e/ec/Memli_Krasniqi_meeting_Majlinda_Kelmendi_%28cropped%29.JPG"],["Q1394493",207,"judo","Robert Van de Walle","C","Robert Van De Walle, né le 20 mai 1954 à Ostende, est un ancien judoka belge.",null,"fr:Robert_Van_de_Walle","c:e/e2/RIAN_archive_563360_Award_ceremony_for_judo_at_1980_Olympics.jpg"],["Q353514",208,"judo","Teddy Riner","PC","Teddy Riner, né le 7 avril 1989 à Pointe-à-Pitre, est un judoka français évoluant dans la catégorie des plus de 100 kg, et a remporté 11 titres mondiaux, soit le plus grand nombre dans l'histoire du judo, et cinq médailles d'or olympique. Il est le plus titré des judokas français.",119,"fr:Teddy_Riner","c:7/7f/Teddy_Riner_Cannes_2016.jpg"],["Q597031",209,"ski","Alexis Pinturault","C","Alexis Pinturault, né le 20 mars 1991 à Moûtiers en Savoie, est un skieur alpin français polyvalent, troisième athlète de son pays à remporter le classement général de la Coupe du monde, à l'issue de la saison 2020-2021, recordman français au nombre de victoires et de podiums, et double champion du monde du combiné alpin.",118,"fr:Alexis_Pinturault","c:3/38/Alexis_Pinturault_aux_Championnats_de_France_de_Slalom_2021.jpg"],["Q1956",210,"ski","Hermann Maier","C","Hermann Maier, né le 7 décembre 1972 à Altenmarkt im Pongau, est un skieur alpin autrichien. Il remporte au cours de sa carrière deux titres olympiques, quatre victoires au classement général de Coupe du monde et trois titres de champion du monde. Il s'illustre notamment dans les disciplines du super G, descente, slalom géant et combiné.","Hermann Maier, né le 7 décembre 1972 à Altenmarkt im Pongau, est un skieur alpin autrichien.","fr:Hermann_Maier","c:a/a0/Hermann_Maier_2.jpg"],["Q530",211,"ski","Ingemar Stenmark","C","Ingemar Stenmark, né le 18 mars 1956 à Joesjö, est un skieur alpin suédois. Il est considéré comme l'un des meilleurs skieurs alpins de l'Histoire, ainsi que l'atteste son palmarès: double champion olympique à Lake Placid en 1980, cinq titres de champion du monde, trois gros globes de cristal, et plusieurs records absolus: huit petits globes du slalom et autant en géant, et surtout quatre-vingt-six succès en Coupe du monde: quarante en slalom et quarante-six en géant.","Ingemar Stenmark, né le 18 mars 1956 à Joesjö, est un skieur alpin suédois.","fr:Ingemar_Stenmark","c:a/af/Ingemar_Stenmark_-_2011.jpg"],["Q10091",212,"ski","Janica Kostelić","C","Janica Kostelić, née le 5 janvier 1982 à Zagreb, est une skieuse alpine croate dont la carrière sportive s'est étendue de 1998 à 2006 au niveau international. Elle est la sœur d'Ivica Kostelić, lui aussi skieur alpin et quadruple médaillé d'argent olympique. Avec quatre médailles d'or et un total de six podiums, elle est pour les compétitions féminines l'athlète la plus titrée et la plus décorée en ski alpin aux Jeux olympiques d'hiver.",118,"fr:Janica_Kostelić","c:7/7e/JanicaKostelic.jpg"],["Q11485",213,"ski","Jean-Claude Killy","C","Jean-Claude Killy, né le 30 août 1943 à Saint-Cloud, est un skieur alpin, coureur automobile et dirigeant français, triple champion olympique de ski alpin à Grenoble en 1968.",115,"fr:Jean-Claude_Killy","c:a/a1/Killy_2011_cropped.JPG"],["Q30293",214,"ski","Lara Gut-Behrami","C","Lara Gut-Behrami, née Lara Gut le 27 avril 1991 à Lugano, est une skieuse alpine suisse qui s'aligne régulièrement dans toutes les disciplines excepté le slalom.",119,"fr:Lara_Gut-Behrami","c:b/b3/2017_Audi_FIS_Ski_Weltcup_Garmisch-Partenkirchen_Damen_-_Lara_Gut_-_by_2eight_-_8SC0746.jpg"],["Q10068",215,"ski","Lindsey Vonn","PC","Lindsey Vonn, née Kildow le 18 octobre 1984 à Saint Paul, dans le Minnesota, est une skieuse alpine américaine.",null,"fr:Lindsey_Vonn","c:a/a5/25th_Laureus_World_Sports_Awards_-_Red_Carpet_-_Lindsey_Vonn_-_240422_181204_%28cropped%29.jpg"],["Q2072",216,"ski","Marcel Hirscher","C","Marcel Hirscher, né le 2 mars 1989 à Annaberg-Lungötz, est un skieur alpin autrichien et néerlandais, spécialiste des épreuves de slalom et de slalom géant, double champion olympique, septuple champion du monde et détenteur du record de victoires au classement général de Coupe du monde de ski alpin qu'il est le seul à avoir remporté à huit reprises, qui plus est consécutivement. Il totalise 67 victoires, ce qui le voit figurer chez les hommes à la deuxième place derrière Ingemar Stenmark.",117,"fr:Marcel_Hirscher","c:7/7e/Hirscher-001.jpg"],["Q359348",217,"ski","Martin Fourcade","C","Martin Fourcade, né le 14 septembre 1988 à Céret dans les Pyrénées-Orientales, est un biathlète français, six fois champion olympique, sept fois vainqueur du classement général de la Coupe du monde et treize fois champion du monde dont la carrière internationale s'étend de 2007 à 2020.",114,"fr:Martin_Fourcade","c:b/b3/Martin_Fourcade_octobre_2017.jpg"],["Q139075",218,"ski","Mikaela Shiffrin","C","Mikaela Shiffrin, née le 13 mars 1995 à Vail dans le Colorado, est une skieuse alpine américaine, triple championne olympique, octuple championne du monde, seule skieuse de l'histoire à compter quatre titres mondiaux gagnés d'affilée dans une discipline, sextuple gagnante du classement général de la Coupe du monde, recordwoman du nombre de premières places en slalom et de victoires en une saison sur le circuit mondial, tous sexes confondus et désormais depuis 2025, comptant plus de 100 victoires en Coupe du monde,…",115,"fr:Mikaela_Shiffrin","c:8/81/Mikaela_Shiffrin_M%C3%A9ribel_2023.jpg"],["Q189408",219,"ski","Ole Einar Bjørndalen","C","Ole Einar Bjørndalen, né le 27 janvier 1974 à Simostranda, est un biathlète norvégien. Il totalise quatorze médailles aux Jeux olympiques d'hiver obtenues entre 1998 et 2014 et est seulement devancé par sa compatriote skieuse de fond Marit Bjørgen qui a battu son record en 2018.","Ole Einar Bjørndalen, né le 27 janvier 1974 à Simostranda, est un biathlète norvégien.","fr:Ole_Einar_Bjørndalen","c:c/c6/2016_Biathlon_World_Championships_2016-03-13_%2826608659465%29.jpg"],["Q10085",220,"ski","Tina Maze","C","Tina Maze, née le 2 mai 1983 à Slovenj Gradec, est une skieuse alpine slovène. Gagnante du classement général de la Coupe du monde en 2013 et double championne olympique en 2014, elle a également remporté quatre titres dans quatre disciplines aux championnats du monde entre 2011 et 2015.","Tina Maze, née le 2 mai 1983 à Slovenj Gradec, est une skieuse alpine slovène.","fr:Tina_Maze","c:f/fd/Internationale_Sportnacht_Davos_2014.jpg"],["Q505423",221,"football_us","Jerry Rice","R","Jerry Rice, né le 13 octobre 1962 à Starkville dans l'État du Mississippi aux États-Unis, est un joueur américain de football américain. Il est considéré comme le meilleur wide receiver et l'un des meilleurs joueurs de l'histoire de la National Football League.",116,"fr:Jerry_Rice","c:f/fb/Jerry_Rice.jpg"],["Q348011",222,"football_us","Joe Montana","R","Joseph Clifford Montana, Jr. dit Joe Montana, né le 11 juin 1956 à New Eagle, est un joueur américain de football américain évoluant au poste de quarterback dans la National Football League entre 1979 et 1994. Il passe les treize premières saisons de sa carrière avec les 49ers de San Francisco et remporte quatre Super Bowls avec l'équipe, étant nommé 3 fois MVP de ces finales et deux fois MVP de la League.","Joseph Clifford Montana, Jr.","fr:Joe_Montana","c:8/8c/Joe_Montana_ESPN_cropped2.jpg"],["Q19667998",223,"football_us","Patrick Mahomes","L","Patrick Lavon Mahomes II, né le 17 septembre 1995 à Tyler, au Texas, est un sportif professionnel américain de football américain jouant au poste de quarterback au sein de la National Football League depuis la saison 2017.",119,"fr:Patrick_Mahomes","c:9/92/Patrick_Mahomes_%2851615475056%29.jpg"],["Q7539",224,"football_us","Peyton Manning","L","Peyton Williams Manning, né le 24 mars 1976 à La Nouvelle-Orléans en Louisiane, est un joueur de football qui a évolué au poste de quarterback dans la National Football League entre 1998 et 2016.",118,"fr:Peyton_Manning","c:c/c0/Peyton_Manning_by_Gage_Skidmore.jpg"],["Q313381",225,"football_us","Tom Brady","M","Thomas Brady, dit Tom Brady, né le 3 août 1977 à San Mateo, est un commentateur sportif et un sportif professionnel américain de football américain ayant évolué pendant 23 saisons dans la National Football League au poste de quarterback.",115,"fr:Tom_Brady","c:7/73/25th_Laureus_World_Sports_Awards_-_Red_Carpet_-_Tom_Brady_-_240422_191334_%28cropped%29_%28cropped%29.jpg"],["Q7836292",226,"football_us","Travis Kelce","L","Travis Kelce, né le 5 octobre 1989 à Westlake en Ohio, est un sportif professionnel américain de football américain jouant au poste de tight end dans la National Football League depuis la saison 2013.",115,"fr:Travis_Kelce","c:f/f5/Travis_Kelce_in_the_Oval_Office_of_the_White_House_on_June_5%2C_2023_-_P20230605AS-0902_%28cropped%29.jpg"],["Q311374",227,"hockey","Aleksandr Ovetchkine","L","Aleksandr Mikhaïlovitch Ovetchkine – en russe: Александр Михайлович Овечкин, et en anglais: Alexander Mikhaylovich Ovechkin, la forme la plus souvent utilisée –, né le 17 septembre 1985 à Moscou en URSS, est un joueur professionnel russe de hockey sur glace.",114,"fr:Aleksandr_Ovetchkine","c:b/b9/Alex_Ovechkin_with_Stanley_Cup.jpg"],["Q2806736",228,"hockey","Connor McDavid","R","Connor Andrew McDavid est un joueur professionnel canadien de hockey sur glace. Il évolue au poste de centre.","Connor Andrew McDavid est un joueur professionnel canadien de hockey sur glace.","fr:Connor_McDavid","c:d/d4/Connor_McDavid_2-FEB-2022.jpg"],["Q316249",229,"hockey","Mario Lemieux","PC","Mario Lemieux, C. Q., O.C., est un joueur canadien de hockey sur glace. Surnommé « Le Magnifique » en raison de son talent et récompensé par de nombreux titres, il est considéré comme l’un des meilleurs joueurs de l’histoire de la Ligue nationale de hockey. Il fait partie du cercle des joueurs de la LNH avec plus de 500 buts, ainsi que de celui de ceux avec plus de 1 000 points et il figure dans les premiers joueurs des différents classements des meneurs de la LNH.","Mario Lemieux, C.","fr:Mario_Lemieux","c:6/6a/Mario_Lemieux_2001.jpg"],["Q311280",230,"hockey","Sidney Crosby","R","Sidney Patrick Crosby OC est un joueur canadien de hockey sur glace professionnel évoluant dans la Ligue nationale de hockey en tant que centre. Il fait ses débuts dans la LNH lors de la saison 2005-2006 après avoir été le premier choix du repêchage la même année. Capitaine des Penguins de Pittsburgh depuis mai 2007, il mène l'équipe à la victoire de la Coupe Stanley à l'issue des saisons 2008-2009, 2015-2016 et 2016-2017.",117,"fr:Sidney_Crosby","c:3/35/Sidney_Crosby_1_2017-05-25_%28Edited%29.jpg"],["Q316864",231,"hockey","Vladislav Tretiak","C","Vladislav Aleksandrovich Tretiak — en russe Владисла́в Алекса́ндрович Третья́к — est un gardien de but de hockey sur glace.",116,"fr:Vladislav_Tretiak","c:1/1e/Vladislav_Tretiak.JPG"],["Q209518",232,"hockey","Wayne Gretzky","E","Wayne Gretzky, O.C., est un joueur professionnel canadien de hockey sur glace qui possède aussi la nationalité américaine. Il joue l'essentiel de sa carrière professionnelle dans la Ligue nationale de hockey et est généralement considéré comme le meilleur joueur de l'histoire du hockey sur glace. Portant le numéro 99 durant sa carrière, il est le seul joueur dont le numéro est retiré pour l'ensemble des équipes de la Ligue nationale de hockey.",110,"fr:Wayne_Gretzky","c:0/03/Wayne_Gretzky_2006-02-18_Turin_001.jpg"],["Q3046479",233,"autre_athlete","Earvin Ngapeth","C","Earvin Ngapeth, né le 12 février 1991 à Saint-Raphaël, est un joueur international français de volley-ball évoluant au poste de réceptionneur-attaquant au Tours Volley-Ball. Son père est Éric Ngapeth, ancien joueur international français de volley-ball. Son frère cadet, Swan, est également joueur de volley-ball. Earvin s’est également lancé dans le Rap sous le nom de Earvin.",118,"fr:Earvin_Ngapeth","c:2/2e/Earvin_Ngapeth_%28Legavolley_2018%29.jpg"],["Q364406",235,"autre_athlete","Kelly Slater","PC","Kelly Slater est un surfeur professionnel américain. Il est considéré comme le meilleur surfeur de tous les temps. Il détient onze titres de champion du monde de surf, remporte à 50 ans et pour la 8e fois le Billabong Pro Pipeline trente ans après sa première victoire et plus de cinquante victoires sur le circuit d'élite WCT ce qui constitue un record.","Kelly Slater est un surfeur professionnel américain.","fr:Kelly_Slater","c:7/72/Kelly_slater.jpg"],["Q1319437",238,"autre_athlete","Michael van Gerwen","C","Michael van Gerwen est un joueur professionnel de fléchettes néerlandais. Il remporte à trois reprises le Championnat du monde en 2014, 2017 et 2019.","Michael van Gerwen est un joueur professionnel de fléchettes néerlandais.","fr:Michael_van_Gerwen","c:6/60/2026-03-26_Premier_League_Darts_%E2%80%93_Night_8_%E2%80%93_Berlin_2026_by_Sandro_Halank%E2%80%93162.jpg"],["Q33228",239,"autre_athlete","Nadia Comăneci","PC","Nadia Comăneci, dont le nom est parfois francisé en Nadia Comaneci, née à Onești le 12 novembre 1961, est une gymnaste roumaine et américaine.",118,"fr:Nadia_Comăneci","c:7/7c/Nadia_Com%C4%83neci_Montreal1976c.jpg"],["Q157809",240,"autre_athlete","Nikola Karabatic","C","Nikola Karabatic, né Nikola Karabatić le 11 avril 1984 à Niš en Serbie, est un joueur français de handball. Il évoluait au poste d'arrière gauche ou de demi-centre.","Nikola Karabatic, né Nikola Karabatić le 11 avril 1984 à Niš en Serbie, est un joueur français de handball.","fr:Nikola_Karabatic","c:3/30/US_Cr%C3%A9teil_-_PSG_Handball_-_29e_journ%C3%A9e_LNH_78.jpg"],["Q190782",241,"autre_athlete","Ronnie O'Sullivan","PC","Ronald Antonio « Ronnie » O'Sullivan est un joueur de snooker professionnel, de billard et écrivain britannique, né le 5 décembre 1975 à Wordsley.",118,"fr:Ronnie_O'Sullivan","c:a/a1/Ronnie_O%E2%80%99Sullivan_at_Snooker_German_Masters_%28DerHexer%29_2015-02-06_07.jpg"],["Q7520267",242,"autre_athlete","Simone Biles","R","Simone Biles, née le 14 mars 1997 à Columbus, est une gymnaste artistique américaine. Elle est considérée comme l'une des meilleures gymnastes de tous les temps. Elle possède également la nationalité bélizienne mais elle représente les États-Unis en compétition.","Simone Biles, née le 14 mars 1997 à Columbus, est une gymnaste artistique américaine.","fr:Simone_Biles","c:f/f6/Simone_Biles_National_Team_2024.jpg",{"cats":["sports","sante_mentale"]}],["Q7855",243,"autre_athlete","Sébastien Loeb","E","Sébastien Loeb, né le 26 février 1974 à Haguenau, est un pilote de rallye français reconverti en rallye-raid après un passage en compétitions sur circuit et en rallycross. Engagé sous les couleurs de Citroën Racing, il remporte avec son copilote Daniel Elena le championnat du monde des rallyes neuf fois consécutivement de 2004 à 2012 au terme de dix saisons complètes.",117,"fr:Sébastien_Loeb","c:2/2d/Dakar_2016_-_Conf%C3%A9rence_de_presse_-_20151118_-_079.jpg",{"cats":["sports","moto"]}],["Q368793",244,"autre_athlete","Sébastien Ogier","R","Sébastien Ogier, né le 17 décembre 1983 à Gap, est un pilote de rallye français.",null,"fr:Sébastien_Ogier","c:5/5b/Rajd_Monte_Carlo_2019_-_S%C3%A9bastien_Ogier_2_%28cropped%29.jpg",{"cats":["sports","moto"]}],["Q134709",245,"autre_athlete","Thierry Omeyer","C","Thierry Omeyer, né le 2 novembre 1976 à Mulhouse, est un joueur français de handball évoluant au poste de gardien de but.",116,"fr:Thierry_Omeyer","c:c/c3/Thierry_Omeyer_20171112.jpg"],["Q316224",246,"autre_athlete","Tony Estanguet","C","Tony Estanguet, né le 6 mai 1978 à Pau, est un athlète et un dirigeant sportif français spécialiste du canoë monoplace slalom dont la carrière au plus haut niveau international s'étend de 2000 à 2012.",118,"fr:Tony_Estanguet","c:5/5b/Tony_Estanguet_at_a_2024_Paralympic_Games_media_conference_in_2024_3.jpg"],["Q295020",247,"autre_athlete","Tony Hawk","R","Tony Hawk, né le 12 mai 1968 à San Diego en Californie, est un skateboarder professionnel et un acteur américain.",null,"fr:Tony_Hawk","c:7/79/Tony_Hawk_2016_%28cropped%29.jpg"],["Q164761",249,"competition","100 mètres","PC","Le 100 mètres est une épreuve d'athlétisme consistant à parcourir, en ligne droite, un sprint sur une distance de 100 mètres. Au niveau professionnel, il est couru en moins de 10 secondes chez les hommes ainsi qu'en moins de 11 secondes chez les femmes. Historiquement, la course de vitesse est l'une des plus anciennes de l'athlétisme puisqu'on en retrouve la trace plusieurs siècles avant l'organisation des premiers Jeux olympiques antiques.",117,"fr:100_mètres_(athlétisme)","c:d/d2/London_2012_Olympic_100m_final_start.jpg"],["Q300008",252,"competition","ATP Tour","R","L'ATP Tour est le principal circuit international de tennis masculin. Son équivalent féminin est le WTA Tour. Organisé par l'Association of Tennis Professionals, il est créé en 1990 en remplacement du Grand Prix tennis circuit. Le circuit secondaire est l'ATP Challenger Tour et le troisième niveau est le circuit masculin de l'ITF.","L'ATP Tour est le principal circuit international de tennis masculin.","fr:ATP_Tour","",{"cats":["sports","tennis"]}],["Q502948",254,"competition","Championnat du monde de snooker","C","Le Championnat du monde de snooker est une compétition de classement de snooker qui rassemble les 16 premiers du classement mondial et 16 autres qualifiés. Le tournoi se déroule depuis 1927 et a actuellement lieu au Crucible Theatre à Sheffield, en Angleterre. Il s'agit du tournoi de snooker le plus prestigieux du circuit en ce qui concerne le prestige et le prix.",112,"fr:Championnat_du_monde_de_snooker","c:e/e8/World_Snooker_Championship_Trophy_%28retouched%29.jpg"],["Q7852",255,"competition","Championnat du monde des rallyes","L","Le championnat du monde des rallyes est une compétition de rallye automobile créée par la Fédération internationale de l'automobile en 1973. Le titre de champion du monde des rallyes constructeurs est attribué dès 1973, le championnat pilotes et le championnat copilotes étant créés en 1979.",118,"fr:Championnat_du_monde_des_rallyes","https://upload.wikimedia.org/wikipedia/fr/thumb/2/2b/WRC_FIA_World_Rally_Logo_2023.svg/330px-WRC_FIA_World_Rally_Logo_2023.svg.png",{"cats":["sports","moto"]}],["Q182653",256,"competition","Championnats du monde d'athlétisme","C","Les Championnats du monde d'athlétisme sont une compétition biennale en plein air organisée par la WA qui désigne un champion du monde pour chaque discipline majeure de l'athlétisme. Il s'agit du troisième plus grand événement sportif dans le monde après les Jeux olympiques et la Coupe du monde de football en ce qui concerne les téléspectateurs et l'impact médiatique. À leur création en 1983, les championnats avaient lieu tous les quatre ans, ils ont lieu tous les deux ans depuis 1991.",116,"fr:Championnats_du_monde_d'athlétisme","c:4/46/Hayward_Field_2021.jpg"],["Q2267539",259,"competition","Classement général du Tour de France","C","Le classement général du Tour de France est un classement du Tour de France cycliste, qui récompense le coureur qui a passé le moins de temps au cours de toutes les étapes d'un Tour, en tenant compte des éventuelles secondes de bonifications obtenues lors d'arrivées d'étape ou en cours d'étape. Ce classement attribue depuis 1919 à son leader le port du maillot jaune.",117,"fr:Classement_général_du_Tour_de_France","c:a/ae/Maillotjaune.jpg"],["Q3087660",260,"competition","Combat du siècle","C","Le Combat du siècle est le nom donné au premier des trois matchs de boxe entre le champion Joe Frazier et le challenger Mohamed Ali qui s'est tenu le 8 mars 1971 au Madison Square Garden de New York.",119,"fr:Combat_du_siècle","c:0/0a/Frazier_vs_Ali_1971_Ajman_stamp.jpg",{"cats":["sports","combat"]}],["Q40970",261,"competition","Comité international olympique","C","Le Comité international olympique est une organisation créée par Pierre de Coubertin en 1894 pour réinstaurer les Jeux olympiques antiques puis organiser cet événement sportif tous les quatre ans, puis en alternant tous les deux ans à partir de 1994, Jeux olympiques d'été et Jeux olympiques d'hiver.",118,"fr:Comité_international_olympique","c:c/c1/Si%C3%A8ge_CIO_2020_%281%29.jpg"],["Q132377",262,"competition","Coupe Davis","PC","La Coupe Davis est un tournoi international annuel de tennis professionnel masculin par nations. Créée en 1900 par Dwight Davis, elle est organisée par la Fédération internationale de tennis.","La Coupe Davis est un tournoi international annuel de tennis professionnel masculin par nations.","fr:Coupe_Davis","c:d/d7/RolandGarrosDavis.jpg",{"cats":["sports","tennis"]}],["Q211872",264,"competition","Coupe Stanley","PC","La coupe Stanley, d'abord appelée Dominion Hockey Challenge Cup, est un trophée de hockey sur glace décerné chaque année depuis 1927 par la Ligue nationale de hockey à l'équipe championne des séries éliminatoires.",114,"fr:Coupe_Stanley","c:4/47/Stanley_Cup%2C_2015.jpg"],["Q184654",265,"competition","Décathlon","PC","Le décathlon est une discipline de l'athlétisme appartenant à la catégorie des épreuves combinées. Il se dispute sur deux jours consécutifs, et en plein air. Il comprend dix épreuves constituées de quatre courses, de trois sauts et de trois lancers. Chaque performance est convertie en points selon un barème officiel et la somme de ces points détermine le classement final.","Le décathlon est une discipline de l'athlétisme appartenant à la catégorie des épreuves combinées.","fr:Décathlon","c:e/e1/DOH70175_decathlon_1500m_vdp_%2848910447798%29.jpg"],["Q170320",266,"competition","Flamme olympique","C","La flamme olympique, appelée aussi torche olympique ou flambeau olympique bien que le Comité international olympique fasse une distinction entre ces termes, est un symbole olympique. Elle fait partie du cérémonial des Jeux olympiques modernes: allumage puis relais de la flamme olympique, le dernier relayeur faisant le tour du stade avant de rejoindre une vasque qu'il embrase grâce à sa torche. Ce symbole n'existait pas dans les Jeux olympiques antiques.",116,"fr:Flamme_olympique","c:f/fe/2002_Winter_Olympics_flame.jpg"],["Q102113",267,"competition","Grand Chelem","R","Au tennis, le Grand Chelem est le fait de remporter, la même année, les quatre tournois majeurs du circuit international organisés sous l'égide de la Fédération internationale de tennis. Ceux-ci sont ainsi appelés « tournois du Grand Chelem ».Ces quatre tournois sont:",106,"fr:Grand_Chelem_(tennis)","https://upload.wikimedia.org/wikipedia/fr/thumb/1/1d/Logo_Roland-Garros.svg/330px-Logo_Roland-Garros.svg.png",{"cats":["sports","tennis"]}],["Q43605",269,"competition","Internationaux de France de tennis","R","Les Internationaux de France, ou tournoi de Roland-Garros, ou plus simplement Roland-Garros par métonymie, est un tournoi de tennis annuel sur terre battue, créé en 1891 sous le nom de Championnat de France de tennis, dans sa forme actuelle depuis 1925 et qui se tient depuis 1928 à Paris, dans le stade Roland-Garros.",113,"fr:Internationaux_de_France_de_tennis","https://upload.wikimedia.org/wikipedia/fr/thumb/1/1d/Logo_Roland-Garros.svg/330px-Logo_Roland-Garros.svg.png",{"cats":["sports","tennis"]}],["Q1338800",270,"competition","Ironman","R","Ironman est, dans le langage commun du triathlon, l'un des plus longs formats de la discipline. D'une distance totale de 226 kilomètres, une compétition Ironman, « Homme de fer » en français, est une course multi-disciplinaire consistant à enchaîner 3,8 km de natation, 180,2 km de cyclisme puis un marathon. Cette appellation est associée au triathlon Ironman d'Hawaï originel créé en 1978 par John et Judy Collins, qui est depuis 1990 le championnat du monde d'Ironman.","Ironman est, dans le langage commun du triathlon, l'un des plus longs formats de la discipline.","fr:Ironman","https://upload.wikimedia.org/wikipedia/fr/thumb/a/a5/LogoIronman2.png/330px-LogoIronman2.png"],["Q5389",271,"competition","Jeux olympiques","E","Les Jeux olympiques, aussi appelés Jeux olympiques modernes, puisqu'ils prolongent la tradition des jeux olympiques de la Grèce antique, sont des événements sportifs internationaux majeurs, regroupant les sports d’été ou d’hiver, auxquels des milliers d’athlètes participent à travers différentes compétitions tous les quatre ans, pour chaque olympiade moderne.",118,"fr:Jeux_olympiques","https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Olympic_rings_without_rims.svg/330px-Olympic_rings_without_rims.svg.png"],["Q82414",272,"competition","Jeux olympiques d'hiver","PC","Les Jeux olympiques d'hiver sont un événement sportif international organisé tous les quatre ans. La première édition des jeux olympiques d’hiver a lieu dans la station française de Chamonix en 1924. Les premiers sports sont le ski de fond, le patinage artistique et de vitesse, le hockey sur glace, le combiné nordique, le saut à ski, le bobsleigh, le curling et la patrouille militaire. Les Jeux olympiques d'hiver ont lieu tous les quatre ans de 1924 à 1936.","Les Jeux olympiques d'hiver sont un événement sportif international organisé tous les quatre ans.","fr:Jeux_olympiques_d'hiver","https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Olympic_rings_without_rims.svg/330px-Olympic_rings_without_rims.svg.png"],["Q4630399",273,"competition","Jeux olympiques d'hiver de 2026","R","Les Jeux olympiques d'hiver de 2026, officiellement appelés les XXVes Jeux olympiques d'hiver, sont célébrés à Milan et Cortina d'Ampezzo, en Italie, du 6 au 22 février 2026. Les deux villes ont été élues lors de la 134e session du Comité international olympique le 24 juin 2019 à Lausanne, en Suisse. L'édition olympique hivernale retourne en Italie, 20 ans après les Jeux de Turin en 2006 et 70 ans après ceux de Cortina d'Ampezzo disputés en 1956.",119,"fr:Jeux_olympiques_d'hiver_de_2026","https://upload.wikimedia.org/wikipedia/fr/thumb/1/13/JO_hiver_2026_logo.png/330px-JO_hiver_2026_logo.png"],["Q159821",274,"competition","Jeux olympiques d'été","PC","Les Jeux olympiques d'été sont une compétition multisports mondiale supervisés par le Comité international olympique et se déroulent tous les quatre ans. Lors de la création des Jeux olympiques d'hiver en 1924 et jusqu'en 1992, les Jeux d'été et d'hiver sont organisés la même année. Depuis 1994, Jeux d'été et d'hiver sont décalés de deux ans.",119,"fr:Jeux_olympiques_d'été","https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Olympic_rings_without_rims.svg/330px-Olympic_rings_without_rims.svg.png"],["Q995653",275,"competition","Jeux olympiques d'été de 2024","R","Les Jeux olympiques d'été de 2024, appelés communément Paris 2024 et officiellement Jeux de la XXXIIIe olympiade de l'ère moderne, ont lieu du 26 juillet au 11 août 2024 à Paris, en France. Désignée officiellement ville-hôte par le Comité international olympique en septembre 2017, la capitale française devient la deuxième ville à célébrer les Jeux olympiques d'été pour la troisième fois après Londres.",115,"fr:Jeux_olympiques_d'été_de_2024","https://upload.wikimedia.org/wikipedia/fr/thumb/6/68/Logo_JO_d%27%C3%A9t%C3%A9_-_Paris_2024.svg/330px-Logo_JO_d%27%C3%A9t%C3%A9_-_Paris_2024.svg.png"],["Q1451505",276,"competition","Jeux olympiques d'été de 2028","E","Les Jeux olympiques d'été de 2028, officiellement appelés les Jeux de la XXXIVe olympiade de l'ère moderne, seront célébrés en 2028 à Los Angeles, aux États-Unis. La ville de Californie est seule candidate à l'organisation de ces Jeux, qui lui sont officiellement attribués le 13 septembre 2017 lors de la 131e session du Comité international olympique, à Lima.",114,"fr:Jeux_olympiques_d'été_de_2028","https://upload.wikimedia.org/wikipedia/fr/thumb/f/f9/Logo_JO_d%27%C3%A9t%C3%A9_-_Los_Angeles_2028.svg/330px-Logo_JO_d%27%C3%A9t%C3%A9_-_Los_Angeles_2028.svg.png"],["Q73633",277,"competition","Jeux paralympiques","C","Les Jeux paralympiques sont une compétition multisports, similaire aux Jeux olympiques, mais réservée aux athlètes présentant un handicap physique — qu'il soit moteur ou visuel — ou mental. Les premiers Jeux reconnus, à la suite des Jeux de Stoke Mandeville, ont eu lieu à Rome en 1960, et 1976 pour les Jeux d'hiver. Ils ont lieu tous les quatre ans, en alternance été / hiver comme les Jeux olympiques, à la suite des Jeux olympiques depuis les Jeux de Séoul en 1988.",114,"fr:Jeux_paralympiques","https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/IPC_logo_%282019%29.svg/330px-IPC_logo_%282019%29.svg.png"],["Q1215892",278,"competition","Ligue nationale de hockey","E","La Ligue nationale de hockey ou LNH est une association sportive professionnelle nord-américaine regroupant des franchises de hockey sur glace du Canada et des États-Unis. Le niveau de jeu de cette ligue est considéré comme le meilleur au monde. Les joueurs qui la composent ont longtemps été en grande majorité d'origine canadienne puis nord-américaine.",111,"fr:Ligue_nationale_de_hockey","https://upload.wikimedia.org/wikipedia/fr/thumb/f/f2/Logo_LNH.svg/330px-Logo_LNH.svg.png"],["Q40244",280,"competition","Marathon","R","Le marathon est une épreuve sportive individuelle de course à pied qui se dispute généralement sur route sur une distance de 42,195 kilomètres.",112,"fr:Marathon_(sport)","c:8/82/Stockholmmarathon_2009-start3.jpg"],["Q826038",281,"competition","Marathon de Boston","C","Le marathon de Boston est une course pédestre de 42,195 km empruntant chaque année depuis 1897 les routes et rues de Boston, habituellement le troisième lundi d'avril. C'est le plus vieux marathon annuel au monde qui a fêté sa 119e édition en 2015. Il fait partie du World Marathon Majors, compétition regroupant sept marathons majeurs.",116,"fr:Marathon_de_Boston","https://upload.wikimedia.org/wikipedia/fr/thumb/2/28/Boston_marathon_-_logo.jpg/330px-Boston_marathon_-_logo.jpg"],["Q1071285",282,"competition","Marathon de Paris","C","Le Marathon de Paris est une épreuve de course à pied de 42,195 km organisée annuellement depuis 1976 dans les rues de Paris. De 1998 à 2026, son organisation était assurée par le Paris Athlétisme Compétition - Club Marathon.",118,"fr:Marathon_de_Paris","https://upload.wikimedia.org/wikipedia/fr/thumb/a/ad/Marathonparislogo-2026.svg/330px-Marathonparislogo-2026.svg.png"],["Q280275",283,"competition","Masters de golf","C","Le Masters est un tournoi annuel de golf organisé par l’Augusta National Golf Club. Créé en 1934 par Bobby Jones et Clifford Roberts, il constitue l’un des quatre tournois majeurs du Grand Chelem de golf masculin, aux côtés de l’Open américain, de l’Open britannique et du Championnat de la PGA. Disputé chaque année au début du mois d’avril, il est traditionnellement le premier tournoi majeur de la saison.","Le Masters est un tournoi annuel de golf organisé par l’Augusta National Golf Club.","fr:Masters_de_golf","https://upload.wikimedia.org/wikipedia/en/thumb/2/23/Masters_Logo.png/330px-Masters_Logo.png"],["Q270907",284,"competition","Masters de tennis masculin","R","Le tournoi des ATP Finals, anciennement appelé Masters, est un tournoi de tennis fondé en 1970, traditionnellement le dernier de la saison ATP.",117,"fr:Masters_de_tennis_masculin","https://upload.wikimedia.org/wikipedia/fr/thumb/0/02/Logo_Nitto_ATP_Finals_2026.svg/330px-Logo_Nitto_ATP_Finals_2026.svg.png",{"cats":["sports","tennis"]}],["Q1215884",287,"competition","National Football League","L","La National Football League, abrégée par son sigle NFL, est une association d'équipes professionnelles de football américain, active aux États-Unis.",114,"fr:National_Football_League","https://upload.wikimedia.org/wikipedia/fr/thumb/1/12/National_Football_League_2008.svg/330px-National_Football_League_2008.svg.png"],["Q848797",288,"competition","Open britannique hommes","C","L'Open britannique, officiellement The Open Championship, est un tournoi annuel de golf masculin organisé par le R&A. Créé en 1860, il est le plus ancien tournoi de golf au monde et constitue l’un des quatre tournois majeurs du Grand Chelem de golf masculin, aux côtés du Masters, de l’Open américain et du Championnat de la PGA. Disputé chaque année au mois de juillet, il est traditionnellement le dernier tournoi majeur de la saison.","L'Open britannique, officiellement The Open Championship, est un tournoi annuel de golf masculin organisé par le R&A.","fr:Open_britannique_hommes","https://upload.wikimedia.org/wikipedia/fr/thumb/1/1d/Open_championship.jpg/330px-Open_championship.jpg"],["Q60874",289,"competition","Open d'Australie","R","L'Open d'Australie est l'un des tournois de tennis de la catégorie du Grand Chelem organisé depuis 1905. Actuellement, il se déroule chaque année au Melbourne Park, à Melbourne en Australie et a lieu au mois de janvier.","L'Open d'Australie est l'un des tournois de tennis de la catégorie du Grand Chelem organisé depuis 1905.","fr:Open_d'Australie","https://upload.wikimedia.org/wikipedia/fr/thumb/6/67/Logo_Open_d%27Australie.svg/330px-Logo_Open_d%27Australie.svg.png",{"cats":["sports","tennis"]}],["Q82984",291,"competition","Pierre de Coubertin","C","Pierre de Coubertin, né Charles Pierre Fredy de Coubertin le 1er janvier 1863 à Paris et mort le 2 septembre 1937 à Genève en Suisse, est le rénovateur des Jeux olympiques qu'il relance à la fin du XIXe siècle, devenant le père des Jeux modernes. Il est au départ un historien et pédagogue français fortement influencé par la culture anglo-saxonne. Il a particulièrement milité pour l'introduction du sport dans les établissements scolaires français.",115,"fr:Pierre_de_Coubertin","c:e/ef/Baron_Pierre_de_Coubertin.jpg"],["Q854376",293,"competition","Ryder Cup","C","La Ryder Cup est un trophée de golf créé en 1927, légué par Samuel Ryder, qui récompense tous les deux ans le vainqueur du tournoi qui oppose par équipe depuis 1979 l'Europe et les États-Unis. La compétition est conjointement administrée par la PGA of America et la PGA European Tour et est disputée alternativement sur des parcours européen et américain.",119,"fr:Ryder_Cup","c:3/35/Ryder_Cup_at_the_2008_PGA_Golf_Show_new.jpg"],["Q185027",294,"competition","Saut à la perche","C","Le saut à la perche est une épreuve d'athlétisme faisant partie des sauts. Elle consiste, après avoir effectué une course d'élan d'une cinquantaine de mètres, à s'aider d'une perche souple pour franchir sans la faire tomber une barre horizontale placée à plusieurs mètres de hauteur. C'est la huitième épreuve du décathlon.","Le saut à la perche est une épreuve d'athlétisme faisant partie des sauts.","fr:Saut_à_la_perche","c:9/9c/Pole_Vault_Sequence_3.jpg"],["Q32096",295,"competition","Super Bowl","R","Le Super Bowl est la finale du championnat organisé par la National Football League, ligue américaine de football américain. Conclusion des séries éliminatoires, il oppose les vainqueurs des deux conférences de la ligue, l'American Football Conference et la National Football Conference. Le match clôt une saison d'environ cinq mois, allant de septembre à février.",113,"fr:Super_Bowl","https://upload.wikimedia.org/wikipedia/fr/thumb/9/9b/Super_Bowl_logo.svg.webp/330px-Super_Bowl_logo.svg.webp"],["Q381360",296,"competition","Symboles olympiques","C","Les symboles olympiques sont des icônes, des drapeaux et des symboles utilisés par le Comité international olympique pour représenter les Jeux olympiques. Certains, comme la flamme olympique, la fanfare et l'hymne olympique, sont plus couramment utilisés lors des compétitions, mais d'autres, comme le drapeau olympique, sont utilisés de façon continue.",116,"fr:Symboles_olympiques","c:4/47/Olympic_rings_on_the_Eiffel_Tower_2024_%2821%29.jpg"],["Q939560",297,"competition","The Rumble in the Jungle","PC","The Rumble in the Jungle est un combat de boxe qui a opposé les Américains Mohamed Ali et George Foreman au Zaïre en 1974 pour le titre de champion du monde poids lourds de boxe anglaise.",116,"fr:The_Rumble_in_the_Jungle","c:1/11/Foreman_tira_golpe_a_clay.jpg",{"cats":["sports","combat"]}],["Q132583058",302,"competition","Tour des Flandres","C","Le Tour des Flandres (De Ronde) est une classique cycliste belge créée en 1913, l'un des cinq « monuments » du cyclisme, célèbre pour ses monts pavés.","","en:Tour_of_Flanders",""],["Q41520",303,"competition","Tournoi de Wimbledon","R","Le tournoi de Wimbledon ou The Championships, souvent abrégé par métonymie en Wimbledon, est un tournoi de tennis se déroulant annuellement dans le quartier éponyme du borough londonien de Merton dans la banlieue sud-ouest de Londres. Joué depuis le 3 juillet 1877, il est le plus ancien tournoi de tennis au monde. Il est depuis ses débuts organisé par l'All England Lawn Tennis and Croquet Club, un club sportif anglais. D'abord uniquement ouvert aux hommes, il s'ouvre aux femmes en 1884.",116,"fr:Tournoi_de_Wimbledon","https://upload.wikimedia.org/wikipedia/fr/thumb/5/50/Logo_Wimbledon.svg/330px-Logo_Wimbledon.svg.png",{"cats":["sports","tennis"]}],["Q186471",305,"competition","Ultimate Fighting Championship","R","L'Ultimate Fighting Championship est une organisation internationale d'arts martiaux mixtes, actuellement reconnue comme la plus importante ligue mondiale de ce sport de combat. La première soirée tenue par la promotion en novembre 1993 à Denver dans le Colorado, se présente comme un tournoi permettant de confronter différents styles d'arts martiaux et sports de combat dans des règles libres. Cet événement est alors souvent considéré comme un pilier de l'avènement des « MMA modernes ».",114,"fr:Ultimate_Fighting_Championship","https://upload.wikimedia.org/wikipedia/commons/thumb/9/92/UFC_Logo.svg/330px-UFC_Logo.svg.png",{"cats":["sports","combat"]}],["Q123577",306,"competition","US Open de tennis","R","L'US Open de tennis est un tournoi de tennis se déroulant annuellement dans le parc municipal de Flushing Meadows - Corona Park à New York, au sein de l'USTA National Tennis Center. Appelé « US National Championships » jusqu'en 1967, il se joue depuis 1881 et a connu plusieurs implantations. D'abord joué à Newport, il déménage ensuite au sein du West Side Tennis Club de Forest Hills avant de s'implanter à Flushing Meadows en 1978.",115,"fr:US_Open_de_tennis","https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/Usopen-horizontal-logo.svg/330px-Usopen-horizontal-logo.svg.png",{"cats":["sports","tennis"]}],["Q724450",308,"competition","World Boxing Council","C","La World Boxing Council est une fédération internationale de boxe anglaise. La WBC est considérée comme l'une des quatre principales organisations internationales de boxe professionnelle avec la WBA, l'IBF et la WBO.","La World Boxing Council est une fédération internationale de boxe anglaise.","fr:World_Boxing_Council","https://upload.wikimedia.org/wikipedia/fr/thumb/7/79/WBC-Logo.jpg/330px-WBC-Logo.jpg",{"cats":["sports","combat"]}],["Q114466",309,"discipline","Arts martiaux mixtes","PC","Les arts martiaux mixtes souvent désignés par le sigle anglais MMA pour mixed martial arts, anciennement appelés combat libre ou free-fight, sont un sport de combat de percussion-préhension, combinant les techniques de percussion, telles que coups de pied, de poing, de genou et de coude, et les techniques de préhension en corps à corps, de projections et de soumission ainsi que les techniques particulières de percussion au sol.",119,"fr:Arts_martiaux_mixtes","c:4/4b/Pins_down.jpg",{"cats":["sports","combat"]}],["Q542",310,"discipline","Athlétisme","C","L’athlétisme est un ensemble d’épreuves sportives codifiées comprenant les courses, sauts, lancers, épreuves combinées et marche. Il s’agit de l’art de dépasser la performance des adversaires en vitesse ou en endurance, en distance ou en hauteur. Les épreuves athlétiques, individuelles ou par équipes, ont varié avec le temps et les mentalités. L'athlétisme est l'un des rares sports universellement pratiqués, que ce soit dans le monde amateur ou au cours de nombreuses compétitions de tous niveaux.",118,"fr:Athlétisme","https://upload.wikimedia.org/wikipedia/commons/thumb/8/8f/Athletics_pictogram.svg/330px-Athletics_pictogram.svg.png"],["Q7291",311,"discipline","Badminton","PC","Le badminton est un sport de raquette nommé d'après le château anglais de Badminton House où il a été codifié à la fin du XIXe siècle, sur la base de pratiques plus anciennes en Europe et en Asie.",118,"fr:Badminton","https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Badminton_pictogram.svg/330px-Badminton_pictogram.svg.png"],["Q5369",312,"discipline","Baseball","R","Le baseball est un sport collectif dérivé des mêmes racines que le cricket, qui se pratique sur un terrain de gazon et de sable. Il se joue avec des battes pour frapper une balle lancée, et des gants pour rattraper la balle. Les origines du baseball prêtent à controverse, mais il est indiscutable que les premières règles modernes ont été codifiées aux États-Unis en 1845.",118,"fr:Baseball","c:4/40/Heyward_lines_into_double_play_%2828356212176%29.jpg"],["Q166788",313,"discipline","Biathlon","C","Le biathlon, du latin bis, « deux fois », et du grec ἆθλον, « combat, lutte », est une épreuve sportive combinant deux disciplines. Par coutume, quand on parle du biathlon, on évoque ce sport d'hiver qui associe le ski de fond au tir à la carabine. D'origine militaire, il combine ainsi l'endurance nécessaire au ski de fond et le calme et l'adresse nécessaires au tir. La maîtrise de ces deux disciplines pourtant antagonistes est le principe même du biathlon, sport olympique depuis les Jeux de Squaw Valley en 1960.",118,"fr:Biathlon","https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Biathlon_pictogram.svg/330px-Biathlon_pictogram.svg.png"],["Q32112",314,"discipline","Boxe","PC","La boxe est une discipline sportive et un sport de combat qui oppose deux adversaires ayant recours à des frappes de percussion.",116,"fr:Boxe","c:4/42/Phenakistoscope_3g07692b.gif"],["Q169737",315,"discipline","Breakdance","C","La breakdance, aussi appelé breaking, break, b-boying, b-girling est un style de danse développé à New York dans les années 1970, caractérisé par ses mouvements de corps saccadés, son aspect acrobatique et ses figures au sol. Un danseur de breaking est appelé Bboy ou b-boy, Bgirl ou b-girl.",116,"fr:Breakdance","https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Breakdancing_pictogram.svg/330px-Breakdancing_pictogram.svg.png"],["Q5375",316,"discipline","Cricket","E","Le cricket est un sport collectif de balle et de batte opposant deux équipes composées généralement de onze joueurs chacune. Il se joue généralement sur un terrain de forme ovale, en herbe, au centre duquel se trouve une zone d'une vingtaine de mètres de longueur, à chaque extrémité de laquelle on trouve une structure de bois, le guichet. Une rencontre est divisée en plusieurs manches.",115,"fr:Cricket","c:e/e5/CricketSCG1.jpg"],["Q2215841",317,"discipline","Cyclisme","C","Le cyclisme est un sport proposant des courses selon plusieurs disciplines dont les principales sont le cyclisme sur route, le cyclisme sur piste, le cyclo-cross, le VTT cross-country, le VTT de descente et le BMX. L'univers du cyclisme inclut également d'autres pratiques comme le cyclisme en salle ou le polo-vélo ou encore, chez les jeunes, l'école de cyclisme. Le sport cycliste est réglementé au niveau mondial par l'Union cycliste internationale.",116,"fr:Cyclisme_(sport)","c:9/9c/%27La_Course_de_12_Heures%27_de_%27La_Bicyclette%27_%28vainqueur_Charles_Nicod%C3%A9mi_en_octobre_1892%29_-_La_Revue_des_sports%2C_15_octobre_1892%2C_p.754.jpg"],["Q22857",318,"discipline","Escalade","C","L’escalade, également appelée grimpe ou parfois varappe, est une pratique et un sport consistant à progresser le long d'une paroi pour atteindre le haut d'un relief ou d'une structure artificielle par un cheminement appelé voie ou itinéraire, avec ou sans l'aide de matériel. Le terrain de pratique va des blocs de faible hauteur aux parois de plusieurs centaines de mètres, en passant par les murs d'escalade. Le pratiquant est couramment appelé « grimpeur ».",117,"fr:Escalade","https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Climbing_pictogram.svg/330px-Climbing_pictogram.svg.png"],["Q12100",319,"discipline","Escrime","PC","L’escrime est un sport de combat. Il s’agit de l’art de toucher un adversaire avec la pointe ou le tranchant d’une arme blanche sur les parties valables sans être touché.","L’escrime est un sport de combat.","fr:Escrime","https://upload.wikimedia.org/wikipedia/commons/thumb/0/02/Fencing_pictogram.svg/330px-Fencing_pictogram.svg.png"],["Q131471",320,"discipline","Fléchettes","C","Les fléchettes sont un jeu comme le tir à l’arc qui consiste à jeter des projectiles munis d'une pointe sur une cible.",null,"fr:Fléchettes","c:f/fb/Darts_in_a_dartboard.jpg"],["Q41323",321,"discipline","Football américain","E","Le football américain est un sport collectif opposant deux équipes de onze joueurs qui alternent entre la défense et l'attaque.",116,"fr:Football_américain","c:2/20/Football_play_from_scrimmage.jpg"],["Q5377",322,"discipline","Golf","PC","Le golf est un sport de précision se jouant en plein air, qui consiste à envoyer une balle dans un trou à l'aide de clubs.",115,"fr:Golf","https://upload.wikimedia.org/wikipedia/commons/thumb/5/5f/Golf_pictogram.svg/330px-Golf_pictogram.svg.png"],["Q326827",323,"discipline","Gymnastique artistique","C","La gymnastique artistique est une discipline athlétique consistant à enchaîner des mouvements acrobatiques sur des agrès. On distingue la gymnastique artistique masculine et la gymnastique artistique féminine. Chaque année se déroulent les championnats du monde de gymnastique artistique sauf les années des Jeux olympiques.",114,"fr:Gymnastique_artistique","https://upload.wikimedia.org/wikipedia/commons/thumb/1/12/Gymnastics_%28artistic%29_pictogram.svg/330px-Gymnastics_%28artistic%29_pictogram.svg.png"],["Q8418",324,"discipline","Handball","C","Le handball (/ɑ̃dbal/, de l'allemand: /ˈhantˌbal/ ) est un sport collectif où deux équipes de sept joueurs s'affrontent avec un ballon utilisé à la main en respectant plusieurs règles sur un terrain rectangulaire de dimensions 40 × 20 m, séparé en deux camps. L'équipe déclarée victorieuse est celle qui a marqué le plus de buts à la fin du temps imparti, soit deux périodes de 30 minutes voire d'éventuelles prolongations.",119,"fr:Handball","https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Handball_pictogram.svg/330px-Handball_pictogram.svg.png"],["Q41466",325,"discipline","Hockey sur glace","PC","Le hockey sur glace, appelé le plus souvent hockey, est un sport d’équipe qui se joue sur une patinoire spécialement aménagée. L’objectif de chaque équipe est de marquer des buts en envoyant un disque de caoutchouc vulcanisé, appelé rondelle ou palet, à l’intérieur du but adverse situé à une extrémité de la patinoire. L’équipe se compose de plusieurs lignes de cinq joueurs, qui se relaient sur la glace, ainsi que d'un gardien de but.",116,"fr:Hockey_sur_glace","https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Ice_hockey_pictogram.svg/330px-Ice_hockey_pictogram.svg.png"],["Q11420",326,"discipline","Judo","PC","Le judo est un art martial, créé au Japon en 1882 par Jigorō Kanō en tant que pédagogie physique, mentale et morale. Par rapport au Kobudō, ou « voie martiale traditionnelle », le judo est ce qu'on appelle un shin budō, c'est-à-dire une « voie martiale moderne », dont une branche est devenue un sport de combat, puis un sport olympique à l'occasion des Jeux olympiques de Tokyo de 1964.","Le judo est un art martial, créé au Japon en 1882 par Jigorō Kanō en tant que pédagogie physique, mentale et morale.","fr:Judo","c:d/de/Uchimata-illustration.jpg",{"cats":["sports","combat"]}],["Q11419",327,"discipline","Karaté","PC","Le karaté est un art martial, dit japonais. Cependant, il est originaire du royaume de Ryūkyū, un ancien royaume indépendant annexé par le Japon en 1879. Il s'est développé sur l'île Okinawa, île principale de l'archipel Ryūkyū, en dérivant de la boxe de la grue blanche, pratiquée dans la province du Fujian, lors d'échanges avec la Chine impériale des Qing.","Le karaté est un art martial, dit japonais.","fr:Karaté","https://upload.wikimedia.org/wikipedia/commons/thumb/b/bb/Karatedo.svg/330px-Karatedo.svg.png",{"cats":["sports","combat"]}],["Q178678",328,"discipline","Kick-boxing","C","Le kick-boxing est un sport de combat de percussion et appartenant au groupe dit des boxes pieds-poings. Il est développé et réglementé au début des années 1960 au Japon, sous l'appellation « kick-boxing japonais », avec tout type de coup de pied sur les membres inférieurs, coups de genou direct, coups de coude et projections de judo, et parallèlement à la même époque aux États-Unis, sous l'appellation « kick-boxing américain », avec coup de pied circulaire à l’endroit en ligne basse – uniquement sur la cuisse.","Le kick-boxing est un sport de combat de percussion et appartenant au groupe dit des boxes pieds-poings.","fr:Kick-boxing","c:8/89/USMC-050716-M-1837P-001.jpg",{"cats":["sports","combat"]}],["Q42486",329,"discipline","Lutte","PC","La lutte est une discipline sportive et un sport de combat. Il en existe un très grand nombre de variétés mais on peut en distinguer trois principales: la lutte libre, la lutte gréco-romaine et la lutte féminine.","La lutte est une discipline sportive et un sport de combat.","fr:Lutte","c:5/5e/Clinching_getting_the_back.jpg",{"cats":["sports","combat"]}],["Q120931",330,"discipline","Muay-thaï","PC","Le muay-thaï, boxe thaïlandaise ou encore boxe thaï, est un art martial et un sport de combat, classé en Occident parmi les boxes pieds-poings. Elle est surnommée l’« art des huit membres » en référence aux huit parties utilisées des bras et des jambes. Les pratiquants sont appelés nak muays.",119,"fr:Muay-thaï","c:9/9a/Muay_Thai_Fight_Us_Vs_Burma_%2880668065%29.jpeg",{"cats":["sports","combat"]}],["Q31920",331,"discipline","Natation sportive","C","La natation sportive consiste à parcourir dans une piscine ou en eau libre, le plus rapidement possible et dans un style codifié par la World Aquatics, une distance donnée, sans l'aide d'aucun accessoire.",114,"fr:Natation_sportive","https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Swimming_pictogram.svg/330px-Swimming_pictogram.svg.png"],["Q1582389",332,"discipline","Padel","E","Le padel est un sport de raquette qui se joue sur un court divisé par un filet, encadré de vitres et grillages.",null,"fr:Padel","c:4/41/Campo_de_Padel.jpg",{"cats":["sports","tennis"]}],["Q842284",335,"discipline","Skateboard","C","Un skateboard, un skate, une planche à roulettes ou un rouli-roulant est un objet composé d'un plateau sous lequel sont fixés deux essieux maintenant chacun deux roues. Un skateboard est utilisé comme moyen de déplacement ou pour réaliser des figures acrobatiques, le plus souvent en environnement urbain, ou dans des espaces spécialement aménagés.",119,"fr:Skateboard","c:2/21/Tony_Hawk_skating_the_Ann_Arbor_skatepark_at_Veteran%27s_Memorial_Park_%28cropped%29.jpg"],["Q186222",336,"discipline","Ski alpin","C","Le ski alpin est un ensemble de disciplines du ski qui se pratiquent dans un contexte de loisirs ou de compétition. C'est un sport olympique depuis 1936, les premiers championnats du monde remontent à 1931 et la Coupe du monde est née en 1967. Toutes ces compétitions se déroulent sous l'égide de la Fédération internationale de ski et de snowboard.","Le ski alpin est un ensemble de disciplines du ski qui se pratiquent dans un contexte de loisirs ou de compétition.","fr:Ski_alpin","https://upload.wikimedia.org/wikipedia/commons/thumb/a/a1/Alpine_skiing_pictogram.svg/330px-Alpine_skiing_pictogram.svg.png"],["Q11015",337,"discipline","Snooker","PC","Le snooker est une des variantes du billard. Il se joue à deux ou en équipes de deux sur une grande table avec une « bille de choc » et des « billes objets »: quinze rouges valant un point chacune et six couleurs: une jaune, une verte, une marron, une bleue, une rose et une noire, valant respectivement de deux à sept points.","Le snooker est une des variantes du billard.","fr:Snooker","https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Billiards_pictogram.svg/330px-Billiards_pictogram.svg.png"],["Q40561",338,"discipline","Sumo","PC","Le sumo est un sport de lutte japonais. Le combat sumo se caractérise par le gabarit des lutteurs ainsi que par les nombreux rites traditionnels qui entourent les combats, et consiste en deux règles simples: les lutteurs ne doivent pas sortir du cercle, ni toucher le sol avec une autre partie du corps que la plante des pieds. Ce sport reste populaire au Japon, même si le baseball et le football le détrônent désormais, notamment chez les jeunes.","Le sumo est un sport de lutte japonais.","fr:Sumo","c:a/ac/Asashoryu_fight_Jan08.JPG",{"cats":["sports","combat"]}],["Q159992",339,"discipline","Surf","C","Le surf, prononcé en français est une pratique physique individuelle de glisse sur les vagues déferlantes, au bord de l'océan.",117,"fr:Surf","c:d/d1/2010_mavericks_competition_edit1.jpg"],["Q847",341,"discipline","Tennis","R","Le tennis est un sport de raquette qui oppose soit deux joueurs soit quatre joueurs qui forment deux équipes de deux.",null,"fr:Tennis","c:9/94/2013_Australian_Open_-_Guillaume_Rufin.jpg",{"cats":["sports","tennis"]}],["Q3930",342,"discipline","Tennis de table","PC","Le tennis de table, appelé aussi ping-pong, est un sport de raquette opposant deux ou quatre joueurs autour d'une table. Le tennis de table est une activité de loisir, mais c'est également un sport olympique depuis 1988.","Le tennis de table, appelé aussi ping-pong, est un sport de raquette opposant deux ou quatre joueurs autour d'une table.","fr:Tennis_de_table","https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Table_tennis_pictogram.svg/330px-Table_tennis_pictogram.svg.png"],["Q108429",343,"discipline","Tir à l'arc","C","Le tir à l'arc est un sport de précision et de concentration dans lequel les compétiteurs tentent de tirer leurs flèches au centre d'une cible avec leur arc. Historiquement, le tir à l'arc a été utilisé pour la chasse et le combat, tandis que dans les temps modernes, son utilisation principale est celle d'une activité sportive. Une personne qui pratique le tir à l'arc est appelée un archer.",112,"fr:Tir_à_l'arc","https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Archery_pictogram.svg/330px-Archery_pictogram.svg.png"],["Q10980",344,"discipline","Triathlon","PC","Le triathlon est un sport constitué de trois épreuves d'endurance enchaînées dans l'ordre suivant: natation, cyclisme et course à pied. Sa forme moderne apparaît officiellement aux États-Unis en 1974 et se développe depuis dans le monde entier. Se pratiquant sur des distances très variées, le triathlon devient discipline olympique en l'an 2000 aux Jeux de Sydney sur la longueur standard de 1 500 mètres de natation, 40 kilomètres de vélo et 10 kilomètres de course à pied.",117,"fr:Triathlon","https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/Triathlon_pictogram.svg/330px-Triathlon_pictogram.svg.png"],["Q1734",345,"discipline","Volley-ball","PC","Le volley-ball, ou volleyball, est un sport collectif opposant deux équipes de 6 joueurs, de 4 joueurs ou de 2 joueurs séparés par un filet de hauteur variable selon le niveau et la catégorie. Ce sport se pratique avec un ballon rond sur un terrain rectangulaire de 18 m de long sur 9 m de large ou de 14 m de long et 7 m de large selon la catégorie.",118,"fr:Volley-ball","https://upload.wikimedia.org/wikipedia/commons/thumb/c/ca/Volleyball_%28indoor%29_pictogram.svg/330px-Volleyball_%28indoor%29_pictogram.svg.png"],["Q7707",346,"discipline","Water-polo","C","Le water-polo est un sport collectif aquatique opposant deux formations de sept joueurs. Il fut codifié au Royaume-Uni à la fin du XIXe siècle et devint sport olympique en 1900 pour les hommes, et en 2000 pour les femmes.","Le water-polo est un sport collectif aquatique opposant deux formations de sept joueurs.","fr:Water-polo","https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Water_polo_pictogram.svg/330px-Water_polo_pictogram.svg.png"],["Q179226",348,"discipline","Équitation","C","L’équitation est la technique de conduite d'un équidé monté, sous l'action humaine. Elle peut être pratiquée comme un art, un loisir, un sport, ou dans le cadre d'un travail. L'être humain qui pratique l'équitation, appelé cavalier ou cavalière, monte sur le dos d'un cheval ou d'un poney dirigé à l'aide de ses mains tenant les rênes, et de ses jambes. L'équitation implique un matériel spécifique, généralement une selle avec des étriers, posée sur un amortisseur et un tapis, sur laquelle les cavaliers s'assoient.","L’équitation est la technique de conduite d'un équidé monté, sous l'action humaine.","fr:Utilisation_du_cheval","c:1/10/4%C3%A8me_manche_du_championnat_suisse_de_Pony_games_2013_-_25082013_-_Laconnex_51.jpg"],["Q55356854",349,"autre_athlete","Alysa Liu","E","Alysa Liu, née le 8 août 2005 à Clovis (Californie), est une patineuse artistique américaine.",null,"fr:Alysa_Liu","https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/Alysa_LIUAsatur_Yesayants_-_YantsImages_8309_%28cropped%29.jpg/3840px-Alysa_LIUAsatur_Yesayants_-_YantsImages_8309_%28cropped%29.jpg"]]]);